import { ref, reactive, computed } from 'vue'

export interface FormField {
  value: any
  error: string | null
  touched: boolean
  validator?: (value: any) => string | null
}

export interface UseFormOptions {
  initialValues?: Record<string, any>
  validators?: Record<string, (value: any) => string | null>
  onSubmit?: (values: Record<string, any>) => Promise<void> | void
}

export function useForm(options: UseFormOptions = {}) {
  const {
    initialValues = {},
    validators = {},
    onSubmit
  } = options

  const fields = reactive<Record<string, FormField>>({})
  const loading = ref(false)
  const globalError = ref<string | null>(null)

  // Initialize fields
  Object.keys(initialValues).forEach(key => {
    fields[key] = {
      value: initialValues[key],
      error: null,
      touched: false,
      validator: validators[key]
    }
  })

  const addField = (name: string, initialValue: any = '', validator?: (value: any) => string | null) => {
    fields[name] = {
      value: initialValue,
      error: null,
      touched: false,
      validator
    }
  }

  const setValue = (name: string, value: any) => {
    if (fields[name]) {
      fields[name].value = value
      fields[name].touched = true
      validateField(name)
    }
  }

  const setError = (name: string, error: string | null) => {
    if (fields[name]) {
      fields[name].error = error
    }
  }

  const validateField = (name: string) => {
    const field = fields[name]
    if (!field || !field.validator) return true

    const error = field.validator(field.value)
    field.error = error
    return !error
  }

  const validateAll = () => {
    let isValid = true
    Object.keys(fields).forEach(name => {
      if (!validateField(name)) {
        isValid = false
      }
    })
    return isValid
  }

  const reset = () => {
    Object.keys(fields).forEach(name => {
      fields[name].value = initialValues[name] || ''
      fields[name].error = null
      fields[name].touched = false
    })
    globalError.value = null
  }

  const submit = async () => {
    if (!validateAll() || !onSubmit) return

    loading.value = true
    globalError.value = null

    try {
      const values = Object.keys(fields).reduce((acc, key) => {
        acc[key] = fields[key].value
        return acc
      }, {} as Record<string, any>)

      await onSubmit(values)
    } catch (error) {
      globalError.value = error instanceof Error ? error.message : 'Une erreur est survenue'
    } finally {
      loading.value = false
    }
  }

  const values = computed(() => {
    return Object.keys(fields).reduce((acc, key) => {
      acc[key] = fields[key].value
      return acc
    }, {} as Record<string, any>)
  })

  const errors = computed(() => {
    return Object.keys(fields).reduce((acc, key) => {
      if (fields[key].error) {
        acc[key] = fields[key].error
      }
      return acc
    }, {} as Record<string, string>)
  })

  const isValid = computed(() => {
    return Object.values(fields).every(field => !field.error)
  })

  const isDirty = computed(() => {
    return Object.values(fields).some(field => field.touched)
  })

  return {
    fields,
    values,
    errors,
    loading,
    globalError,
    isValid,
    isDirty,
    addField,
    setValue,
    setError,
    validateField,
    validateAll,
    reset,
    submit
  }
}

import { ref } from 'vue'
import { apiService } from '@/services/api'
import type { Category } from '@/types'

const categories = ref<Category[]>([])
const loading = ref(false)

export const useCategories = () => {
  const loadCategories = async () => {
    if (categories.value.length > 0) {
      return // Already loaded
    }

    loading.value = true
    try {
      const response = await apiService.getCategories()
      if (response.success && response.data) {
        categories.value = response.data
      }
    } catch (error) {
      console.error('Error loading categories:', error)
    } finally {
      loading.value = false
    }
  }

  return {
    categories,
    loading,
    loadCategories
  }
}

import { computed, ref } from 'vue'

// Feature flags from environment variables
const DS_2025_ENABLED = import.meta.env.VITE_DS_2025 === 'true'
const BUTTON_2025_ENABLED = import.meta.env.VITE_BUTTON_2025 === 'true'
const CARD_2025_ENABLED = import.meta.env.VITE_CARD_2025 === 'true'
const BADGE_2025_ENABLED = import.meta.env.VITE_BADGE_2025 === 'true'
const MIGRATION_DEBUG = import.meta.env.VITE_MIGRATION_DEBUG === 'true'

// Global design system state
const designSystemState = ref({
  globalEnabled: DS_2025_ENABLED,
  components: {
    button: BUTTON_2025_ENABLED,
    card: CARD_2025_ENABLED,
    badge: BADGE_2025_ENABLED
  },
  debug: MIGRATION_DEBUG
})

/**
 * Main composable for Design System 2025 feature flags
 */
export function useDesignSystem2025() {
  // Global enable/disable
  const isEnabled = computed(() => designSystemState.value.globalEnabled)

  // Component-specific flags
  const components = computed(() => designSystemState.value.components)

  // Debug mode
  const isDebugMode = computed(() => designSystemState.value.debug)

  // Toggle functions (for runtime testing)
  const toggleGlobal = () => {
    designSystemState.value.globalEnabled = !designSystemState.value.globalEnabled
    if (isDebugMode.value) {
      console.log('🎨 Design System 2025 Global:', designSystemState.value.globalEnabled)
    }
  }

  const toggleComponent = (component: keyof typeof designSystemState.value.components) => {
    designSystemState.value.components[component] = !designSystemState.value.components[component]
    if (isDebugMode.value) {
      console.log(`🧩 Component ${component} 2025:`, designSystemState.value.components[component])
    }
  }

  // Helper to check if specific component should use 2025 version
  const shouldUse2025 = (component: keyof typeof designSystemState.value.components) => {
    return isEnabled.value || components.value[component]
  }

  // Debug logger
  const logMigration = (component: string, action: string, details?: any) => {
    if (isDebugMode.value) {
      console.log(`🔄 Migration [${component}]:`, action, details)
    }
  }

  return {
    // State
    isEnabled,
    components,
    isDebugMode,

    // Methods
    toggleGlobal,
    toggleComponent,
    shouldUse2025,
    logMigration,

    // Specific component helpers
    useButton2025: () => shouldUse2025('button'),
    useCard2025: () => shouldUse2025('card'),
    useBadge2025: () => shouldUse2025('badge')
  }
}

/**
 * Clean feature flag management for 2025 Design System
 * Legacy class mapping functions removed - direct component migration preferred
 */

import { ref, computed, readonly } from 'vue'
import type { ErrorInfo, ErrorContext, ErrorSeverity } from '@/utils/errorTypes'

const globalErrors = ref<ErrorInfo[]>([])
const isOnline = ref(navigator.onLine)
const retryQueue = ref<(() => Promise<void>)[]>([])

export function useErrorHandler() {
  const hasErrors = computed(() => globalErrors.value.length > 0)
  const criticalErrors = computed(() =>
    globalErrors.value.filter(error => error.severity === 'critical')
  )

  const handleError = (
    error: Error | unknown,
    context: ErrorContext = {},
    severity: ErrorSeverity = 'error'
  ): ErrorInfo => {
    const timestamp = Date.now()
    const errorInfo: ErrorInfo = {
      id: generateErrorId(),
      message: getErrorMessage(error),
      severity,
      context,
      timestamp,
      stack: error instanceof Error ? error.stack : undefined,
      retryable: isRetryableError(error),
      userMessage: getUserFriendlyMessage(error, context)
    }

    globalErrors.value.push(errorInfo)

    if (severity !== 'critical') {
      setTimeout(() => {
        removeError(errorInfo.id)
      }, 10000)
    }

    logError(errorInfo)
    return errorInfo
  }

  const handleApiError = (error: unknown, endpoint: string, retryFn?: () => Promise<void>) => {
    const context: ErrorContext = {
      type: 'api',
      endpoint,
      userAgent: navigator.userAgent,
      online: isOnline.value
    }

    if (!isOnline.value) {
      return handleError(
        new Error('Network unavailable'),
        context,
        'warning'
      )
    }

    if (isAuthError(error)) {
      context.type = 'auth'
      return handleError(error, context, 'critical')
    }

    if (isValidationError(error)) {
      context.type = 'validation'
      return handleError(error, context, 'warning')
    }

    if (isServerError(error)) {
      context.type = 'server'
      if (retryFn) {
        retryQueue.value.push(retryFn)
      }
      return handleError(error, context, 'error')
    }

    return handleError(error, context, 'error')
  }

  const removeError = (errorId: string) => {
    const index = globalErrors.value.findIndex(e => e.id === errorId)
    if (index !== -1) {
      globalErrors.value.splice(index, 1)
    }
  }

  const clearErrors = () => {
    globalErrors.value = []
  }

  const setupNetworkMonitoring = () => {
    window.addEventListener('online', () => {
      isOnline.value = true
    })

    window.addEventListener('offline', () => {
      isOnline.value = false
      handleError(
        new Error('Connection lost'),
        { type: 'network' },
        'warning'
      )
    })
  }

  return {
    globalErrors: readonly(globalErrors),
    hasErrors,
    criticalErrors,
    isOnline: readonly(isOnline),
    handleError,
    handleApiError,
    removeError,
    clearErrors,
    setupNetworkMonitoring
  }
}

function generateErrorId(): string {
  const timestamp = Date.now()
  const random = Math.random().toString(36).substr(2, 9)
  return `err_${timestamp}_${random}`
}

function getErrorMessage(error: unknown): string {
  if (error instanceof Error) return error.message
  if (typeof error === 'string') return error
  return 'Une erreur inconnue est survenue'
}

function getUserFriendlyMessage(error: unknown, context: ErrorContext): string {
  const errorMessage = getErrorMessage(error).toLowerCase()

  if (!navigator.onLine || errorMessage.includes('network')) {
    return 'Problème de connexion internet. Vérifiez votre connexion et réessayez.'
  }

  if (context.type === 'auth' || errorMessage.includes('unauthorized')) {
    return 'Votre session a expiré. Veuillez vous reconnecter.'
  }

  if (context.type === 'validation' || errorMessage.includes('validation')) {
    return 'Veuillez vérifier les informations saisies et réessayer.'
  }

  if (context.type === 'server' || errorMessage.includes('500')) {
    return 'Problème temporaire du serveur. Nous travaillons à le résoudre.'
  }

  return 'Une erreur inattendue est survenue. Veuillez réessayer.'
}

function isRetryableError(error: unknown): boolean {
  const message = getErrorMessage(error).toLowerCase()
  return !navigator.onLine ||
         message.includes('network') ||
         message.includes('500') ||
         message.includes('timeout')
}

function isAuthError(error: unknown): boolean {
  const message = getErrorMessage(error).toLowerCase()
  return message.includes('unauthorized') || message.includes('401')
}

function isValidationError(error: unknown): boolean {
  const message = getErrorMessage(error).toLowerCase()
  return message.includes('validation') || message.includes('400')
}

function isServerError(error: unknown): boolean {
  const message = getErrorMessage(error).toLowerCase()
  return message.includes('500') || message.includes('502') || message.includes('503')
}

function logError(errorInfo: ErrorInfo) {
  if (import.meta.env.DEV) {
    console.group(`🚨 Error [${errorInfo.severity}]`)
    console.error('Message:', errorInfo.message)
    console.error('Context:', errorInfo.context)
    console.groupEnd()
  }
}

import { ref, readonly } from 'vue'

interface ErrorReport {
  errorId: string
  component?: string
  userAgent: string
  url: string
  timestamp: number
  retryCount: number
  userId?: string
  sessionId?: string
}

interface ErrorMetrics {
  totalErrors: number
  criticalErrors: number
  resolvedErrors: number
  averageResolutionTime: number
}

interface Breadcrumb {
  id: string
  type: 'navigation' | 'click' | 'input' | 'error'
  message: string
  timestamp: number
  data?: Record<string, unknown>
  level?: 'info' | 'warning' | 'error'
  category?: string
}

interface UserAction {
  id: string
  type: string
  target: string
  timestamp: number
  metadata?: Record<string, unknown>
  action?: string
  data?: Record<string, unknown>
}

// Extended error queue item for ErrorDashboard compatibility
interface ErrorQueueItem {
  error: Error
  context: ErrorReport
  metadata?: {
    severity?: 'low' | 'medium' | 'high' | 'critical'
    category?: string
  }
}

const errorReports = ref<ErrorReport[]>([])
const errorQueue = ref<ErrorQueueItem[]>([])
const breadcrumbs = ref<Breadcrumb[]>([])
const userActions = ref<UserAction[]>([])
const isReporting = ref(false)

export function useErrorReporting() {
  const reportError = async (error: Error, context: ErrorReport) => {
    const report: ErrorReport = {
      ...context,
      errorId: context.errorId || generateReportId()
    }
    errorReports.value.push(report)

    // Also add to error queue for ErrorDashboard
    errorQueue.value.push({
      error,
      context: report,
      metadata: {
        severity: 'low',
        category: 'runtime'
      }
    })

    if (import.meta.env.PROD) {
      try {
        isReporting.value = true
        console.log('Error reported:', { error, context })
      } catch (reportingError) {
        console.error('Failed to report error:', reportingError)
      } finally {
        isReporting.value = false
      }
    }
  }

  const getErrorMetrics = (): ErrorMetrics => {
    const total = errorReports.value.length
    const critical = errorReports.value.filter(r =>
      r.component && r.component.includes('critical')
    ).length

    return {
      totalErrors: total,
      criticalErrors: critical,
      resolvedErrors: 0,
      averageResolutionTime: 0
    }
  }

  const clearReports = () => {
    errorReports.value = []
  }

  const clearErrorQueue = () => {
    errorQueue.value = []
  }

  const clearBreadcrumbs = () => {
    breadcrumbs.value = []
  }

  const clearUserActions = () => {
    userActions.value = []
  }

  const clearAll = () => {
    errorReports.value = []
    errorQueue.value = []
    breadcrumbs.value = []
    userActions.value = []
  }

  return {
    errorReports: readonly(errorReports),
    errorQueue: readonly(errorQueue),
    breadcrumbs: readonly(breadcrumbs),
    userActions: readonly(userActions),
    isReporting: readonly(isReporting),
    reportError,
    getErrorMetrics,
    clearReports,
    clearErrorQueue,
    clearBreadcrumbs,
    clearUserActions,
    clearAll
  }
}

function generateReportId(): string {
  const timestamp = Date.now()
  const random = Math.random().toString(36).substr(2, 9)
  return `report_${timestamp}_${random}`
}

import { ref } from 'vue'

export interface GeolocationCoords {
  latitude: number
  longitude: number
  accuracy?: number
  timestamp?: number
}

export interface GeolocationError {
  code: number
  message: string
  type: 'PERMISSION_DENIED' | 'POSITION_UNAVAILABLE' | 'TIMEOUT' | 'UNSUPPORTED'
}

export interface GeolocationOptions {
  enableHighAccuracy?: boolean
  timeout?: number
  maximumAge?: number
}

export const useGeolocation = () => {
  const position = ref<GeolocationCoords | null>(null)
  const error = ref<GeolocationError | null>(null)
  const isLoading = ref(false)
  const isSupported = 'geolocation' in navigator

  // Default options
  const defaultOptions: GeolocationOptions = {
    enableHighAccuracy: true,
    timeout: 10000,
    maximumAge: 300000 // 5 minutes
  }

  /**
   * Get current position
   */
  const getCurrentPosition = async (options: GeolocationOptions = {}): Promise<GeolocationCoords | null> => {
    if (!isSupported) {
      const err: GeolocationError = {
        code: 0,
        message: 'Géolocalisation non supportée par ce navigateur',
        type: 'UNSUPPORTED'
      }
      error.value = err
      throw err
    }

    isLoading.value = true
    error.value = null

    const finalOptions = { ...defaultOptions, ...options }

    return new Promise((resolve, reject) => {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          const coords: GeolocationCoords = {
            latitude: pos.coords.latitude,
            longitude: pos.coords.longitude,
            accuracy: pos.coords.accuracy,
            timestamp: pos.timestamp
          }

          position.value = coords
          isLoading.value = false
          resolve(coords)
        },
        (err) => {
          isLoading.value = false

          let errorType: GeolocationError['type']
          let message: string

          switch (err.code) {
            case err.PERMISSION_DENIED:
              errorType = 'PERMISSION_DENIED'
              message = 'Autorisation de géolocalisation refusée'
              break
            case err.POSITION_UNAVAILABLE:
              errorType = 'POSITION_UNAVAILABLE'
              message = 'Position non disponible'
              break
            case err.TIMEOUT:
              errorType = 'TIMEOUT'
              message = 'Délai de géolocalisation dépassé'
              break
            default:
              errorType = 'POSITION_UNAVAILABLE'
              message = 'Erreur de géolocalisation inconnue'
              break
          }

          const geolocationError: GeolocationError = {
            code: err.code,
            message,
            type: errorType
          }

          error.value = geolocationError
          reject(geolocationError)
        },
        finalOptions
      )
    })
  }

  /**
   * Watch position changes
   */
  const watchPosition = (options: GeolocationOptions = {}) => {
    if (!isSupported) {
      console.warn('Géolocalisation non supportée')
      return null
    }

    const finalOptions = { ...defaultOptions, ...options }

    const watchId = navigator.geolocation.watchPosition(
      (pos) => {
        position.value = {
          latitude: pos.coords.latitude,
          longitude: pos.coords.longitude,
          accuracy: pos.coords.accuracy,
          timestamp: pos.timestamp
        }
        error.value = null
      },
      (err) => {
        let errorType: GeolocationError['type']
        let message: string

        switch (err.code) {
          case err.PERMISSION_DENIED:
            errorType = 'PERMISSION_DENIED'
            message = 'Autorisation de géolocalisation refusée'
            break
          case err.POSITION_UNAVAILABLE:
            errorType = 'POSITION_UNAVAILABLE'
            message = 'Position non disponible'
            break
          case err.TIMEOUT:
            errorType = 'TIMEOUT'
            message = 'Délai de géolocalisation dépassé'
            break
          default:
            errorType = 'POSITION_UNAVAILABLE'
            message = 'Erreur de géolocalisation inconnue'
            break
        }

        error.value = {
          code: err.code,
          message,
          type: errorType
        }
      },
      finalOptions
    )

    return watchId
  }

  /**
   * Stop watching position
   */
  const clearWatch = (watchId: number) => {
    if (isSupported) {
      navigator.geolocation.clearWatch(watchId)
    }
  }

  /**
   * Calculate distance between two points (Haversine formula)
   */
  const calculateDistance = (
    pos1: GeolocationCoords,
    pos2: GeolocationCoords
  ): number => {
    const R = 6371 // Earth's radius in kilometers
    const dLat = toRadians(pos2.latitude - pos1.latitude)
    const dLon = toRadians(pos2.longitude - pos1.longitude)

    const a =
      Math.sin(dLat / 2) * Math.sin(dLat / 2) +
      Math.cos(toRadians(pos1.latitude)) *
      Math.cos(toRadians(pos2.latitude)) *
      Math.sin(dLon / 2) * Math.sin(dLon / 2)

    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a))

    return R * c
  }

  /**
   * Convert degrees to radians
   */
  const toRadians = (degrees: number): number => {
    return degrees * (Math.PI / 180)
  }

  /**
   * Check if coordinates are within a certain radius
   */
  const isWithinRadius = (
    center: GeolocationCoords,
    point: GeolocationCoords,
    radiusKm: number
  ): boolean => {
    const distance = calculateDistance(center, point)
    return distance <= radiusKm
  }

  /**
   * Get human-readable distance string
   */
  const formatDistance = (distanceKm: number): string => {
    if (distanceKm < 1) {
      return `${Math.round(distanceKm * 1000)} m`
    } else if (distanceKm < 10) {
      return `${distanceKm.toFixed(1)} km`
    } else {
      return `${Math.round(distanceKm)} km`
    }
  }

  /**
   * Get location name from coordinates (reverse geocoding)
   * Note: This would require an external service like Google Maps or OpenStreetMap
   */
  const getLocationName = async (coords: GeolocationCoords): Promise<string | null> => {
    try {
      // Using OpenStreetMap Nominatim service (free)
      const response = await fetch(
        `https://nominatim.openstreetmap.org/reverse?lat=${coords.latitude}&lon=${coords.longitude}&format=json&accept-language=fr`
      )

      if (!response.ok) throw new Error('Reverse geocoding failed')

      const data = await response.json()

      if (data.display_name) {
        return data.display_name
      }

      return null
    } catch (err) {
      console.warn('Reverse geocoding failed:', err)
      return null
    }
  }

  /**
   * Reset state
   */
  const reset = () => {
    position.value = null
    error.value = null
    isLoading.value = false
  }

  return {
    // State
    position,
    error,
    isLoading,
    isSupported,

    // Methods
    getCurrentPosition,
    watchPosition,
    clearWatch,
    calculateDistance,
    isWithinRadius,
    formatDistance,
    getLocationName,
    reset
  }
}

export default useGeolocation

import { ref, computed } from 'vue'
import { notify } from '@/composables/useNotifications'
import apiService from '@/services/api'
import type {
  LoyaltyPointsSummary,
  LoyaltyParticipantSummary,
  LoyaltyAwardPayload,
  LoyaltyRedemptionPayload
} from '@/types'

export const useLoyaltyPoints = () => {
  // State
  const points = ref<LoyaltyPointsSummary | null>(null)
  const allUsersPoints = ref<LoyaltyParticipantSummary[]>([])
  const loading = ref(false)
  const error = ref<string | null>(null)

  // Computed
  const totalPoints = computed(() => points.value?.total_points || 0)
  const expiringPoints = computed(() => points.value?.expiring_soon || 0)
  const recentHistory = computed(() => points.value?.recent_history || [])
  const pointsBreakdown = computed(() => points.value?.breakdown || [])

  const getErrorMessage = (err: unknown, fallback: string): string => {
    if (err instanceof Error && err.message) {
      return err.message
    }

    if (typeof err === 'string' && err.length > 0) {
      return err
    }

    if (err && typeof err === 'object' && 'message' in err && typeof (err as any).message === 'string') {
      return (err as { message: string }).message
    }

    return fallback
  }

  const reportError = (err: unknown, fallback: string, title?: string) => {
    const message = getErrorMessage(err, fallback)
    error.value = message
    notify.error(message, title)
  }

  // Methods
  const fetchMyPoints = async (): Promise<void> => {
    loading.value = true
    error.value = null

    try {
      const response = await apiService.getLoyaltyPoints()
      points.value = response.data
    } catch (err) {
      reportError(err, 'Erreur lors de la récupération des points')
    } finally {
      loading.value = false
    }
  }

  const awardPoints = async (
    data: LoyaltyAwardPayload,
    scope: 'merchant' | 'admin' = 'merchant'
  ): Promise<boolean> => {
    loading.value = true
    error.value = null

    try {
      const response = await apiService.awardLoyaltyPoints(data, scope)
      notify.success(response.message || 'Points attribués avec succès')
      return true
    } catch (err) {
      reportError(err, 'Erreur lors de l\'attribution des points')
      return false
    } finally {
      loading.value = false
    }
  }

  const redeemPoints = async (data: LoyaltyRedemptionPayload): Promise<boolean> => {
    loading.value = true
    error.value = null

    try {
      const response = await apiService.redeemLoyaltyPoints(data)
      notify.success(response.message || 'Points échangés avec succès')
      await fetchMyPoints()
      return true
    } catch (err) {
      reportError(
        err,
        'Impossible d\'échanger vos points. Vérifiez que vous avez suffisamment de points.',
        'Erreur d\'échange'
      )
      return false
    } finally {
      loading.value = false
    }
  }

  const fetchAllUsersPoints = async (scope: 'merchant' | 'admin' = 'merchant'): Promise<void> => {
    loading.value = true
    error.value = null

    try {
      const response = await apiService.getLoyaltyParticipants(scope)
      allUsersPoints.value = response.data
    } catch (err) {
      reportError(err, 'Erreur lors de la récupération des points')
    } finally {
      loading.value = false
    }
  }

  // Helper functions
  const formatPoints = (points: number): string => {
    return new Intl.NumberFormat('fr-FR').format(points)
  }

  const getPointTypeLabel = (type: string): string => {
    const labels: Record<string, string> = {
      'purchase': 'Achat',
      'review': 'Avis',
      'referral': 'Parrainage',
      'bonus': 'Bonus',
      'redemption': 'Échange'
    }
    return labels[type] || type
  }

  const getPointTypeColor = (type: string): string => {
    const colors: Record<string, string> = {
      'purchase': 'text-success',
      'review': 'text-info',
      'referral': 'text-purple-600',
      'bonus': 'text-warning',
      'redemption': 'text-error'
    }
    return colors[type] || 'text-gray-600'
  }

  const canRedeem = (pointsToRedeem: number): boolean => {
    return totalPoints.value >= pointsToRedeem && pointsToRedeem > 0
  }

  return {
    // State
    points,
    allUsersPoints,
    loading,
    error,

    // Computed
    totalPoints,
    expiringPoints,
    recentHistory,
    pointsBreakdown,

    // Methods
    fetchMyPoints,
    awardPoints,
    redeemPoints,
    fetchAllUsersPoints,

    // Helpers
    formatPoints,
    getPointTypeLabel,
    getPointTypeColor,
    canRedeem
  }
}

import { ref, computed } from 'vue'
import { notify } from './useNotifications'

interface NetworkError {
  message: string
  code?: string
  retryable: boolean
}

interface RetryConfig {
  maxRetries: number
  baseDelay: number
  maxDelay: number
  backoffFactor: number
}

const defaultRetryConfig: RetryConfig = {
  maxRetries: 3,
  baseDelay: 1000,
  maxDelay: 10000,
  backoffFactor: 2
}

const isOnline = ref(navigator.onLine)
const pendingRequests = ref(new Map<string, any>())

// Écouter les changements de connexion
window.addEventListener('online', () => {
  isOnline.value = true
  notify.success('Connexion rétablie', 'En ligne')

  // Relancer les requêtes en attente
  // Requêtes seront rejouées automatiquement
})

window.addEventListener('offline', () => {
  isOnline.value = false
  notify.warning('Connexion interrompue. Les données seront synchronisées à la reconnexion.', 'Hors ligne')
})

export const useNetworkError = () => {
  const isNetworkError = (error: any): boolean => {
    if (!error) return false

    const errorMessage = error.message?.toLowerCase() || ''
    const errorName = error.name?.toLowerCase() || ''

    return (
      errorMessage.includes('network') ||
      errorMessage.includes('fetch') ||
      errorMessage.includes('connection') ||
      errorName.includes('networkerror') ||
      error.code === 'NETWORK_ERROR' ||
      error.status === 0
    )
  }

  const isRetryableError = (error: any): boolean => {
    if (isNetworkError(error)) return true

    // Codes d'erreur HTTP retryables
    const retryableStatusCodes = [408, 429, 500, 502, 503, 504]
    return retryableStatusCodes.includes(error.status)
  }

  const getErrorMessage = (error: any): NetworkError => {
    if (!isOnline.value) {
      return {
        message: 'Pas de connexion internet. Vos actions seront synchronisées une fois la connexion rétablie.',
        code: 'OFFLINE',
        retryable: true
      }
    }

    if (isNetworkError(error)) {
      return {
        message: 'Problème de connexion au serveur. Nouvelle tentative en cours...',
        code: 'NETWORK_ERROR',
        retryable: true
      }
    }

    if (error.status === 429) {
      return {
        message: 'Trop de requêtes. Veuillez patienter un moment.',
        code: 'RATE_LIMITED',
        retryable: true
      }
    }

    if (error.status >= 500) {
      return {
        message: 'Problème temporaire du serveur. Nouvelle tentative en cours...',
        code: 'SERVER_ERROR',
        retryable: true
      }
    }

    return {
      message: error.message || 'Une erreur inattendue s\'est produite',
      code: 'UNKNOWN_ERROR',
      retryable: false
    }
  }

  const sleep = (ms: number): Promise<void> => {
    return new Promise(resolve => setTimeout(resolve, ms))
  }

  const calculateDelay = (attempt: number, config: RetryConfig): number => {
    const delay = config.baseDelay * Math.pow(config.backoffFactor, attempt)
    return Math.min(delay, config.maxDelay)
  }

  const withRetry = async <T>(
    fn: () => Promise<T>,
    config: Partial<RetryConfig> = {},
    requestKey?: string
  ): Promise<T> => {
    const finalConfig = { ...defaultRetryConfig, ...config }
    let lastError: any

    for (let attempt = 0; attempt <= finalConfig.maxRetries; attempt++) {
      try {
        // Si on est hors ligne et que c'est la première tentative, stocker la requête
        if (!isOnline.value && attempt === 0 && requestKey) {
          pendingRequests.value.set(requestKey, { fn, config, requestKey })
          throw new Error('OFFLINE')
        }

        const result = await fn()

        // Nettoyer la requête en attente en cas de succès
        if (requestKey) {
          pendingRequests.value.delete(requestKey)
        }

        return result
      } catch (error) {
        lastError = error

        const networkError = getErrorMessage(error)

        // Si l'erreur n'est pas retryable, échouer immédiatement
        if (!networkError.retryable) {
          throw error
        }

        // Si c'est le dernier essai, échouer
        if (attempt === finalConfig.maxRetries) {
          if (!isOnline.value) {
            notify.warning(networkError.message, 'Mode hors ligne')
          } else {
            notify.error(`Impossible de se connecter après ${finalConfig.maxRetries + 1} tentatives`, 'Erreur réseau')
          }
          throw error
        }

        // Attendre avant de retry
        const delay = calculateDelay(attempt, finalConfig)

        if (attempt === 0) {
          notify.warning(networkError.message, 'Nouvelle tentative...')
        }

        await sleep(delay)
      }
    }

    throw lastError
  }

  const replayPendingRequests = async () => {
    if (!isOnline.value || pendingRequests.value.size === 0) return

    const requests = Array.from(pendingRequests.value.entries())
    pendingRequests.value.clear()

    for (const [_, { fn, config, requestKey }] of requests) {
      try {
        await withRetry(fn, config, requestKey)
        notify.success('Données synchronisées', 'Succès')
      } catch (error) {
        notify.error('Impossible de synchroniser certaines données', 'Erreur de synchronisation')
      }
    }
  }

  // Wrapper pour les requêtes fetch avec retry automatique
  const fetchWithRetry = async (
    url: string,
    options: RequestInit = {},
    retryConfig?: Partial<RetryConfig>
  ): Promise<Response> => {
    const requestKey = `${options.method || 'GET'}:${url}`

    return withRetry(async () => {
      const response = await fetch(url, options)

      if (!response.ok && isRetryableError({ status: response.status })) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`)
      }

      return response
    }, retryConfig, requestKey)
  }

  return {
    isOnline: computed(() => isOnline.value),
    pendingRequestsCount: computed(() => pendingRequests.value.size),
    isNetworkError,
    isRetryableError,
    getErrorMessage,
    withRetry,
    fetchWithRetry,
    replayPendingRequests
  }
}

import { ref, computed } from 'vue'

export interface Notification {
  id: string
  type: 'success' | 'error' | 'warning' | 'info'
  title?: string
  message: string
  autoClose?: boolean
  duration?: number
  progress?: number
  timer?: NodeJS.Timeout
  action?: {
    label: string
    callback: () => void | Promise<void>
  }
  onClose?: () => void
}

const notifications = ref<Notification[]>([])
const notificationIdCounter = ref(0)

export const useNotifications = () => {
  const addNotification = (notification: Omit<Notification, 'id' | 'progress' | 'timer'>) => {
    const id = `notification-${++notificationIdCounter.value}`
    const autoClose = notification.autoClose !== false
    const duration = notification.duration || 5000

    const newNotification: Notification = {
      ...notification,
      id,
      autoClose,
      duration,
      progress: 100
    }

    notifications.value.push(newNotification)

    if (autoClose) {
      let progress = 100
      const interval = 50
      const step = (interval / duration) * 100

      const timer = setInterval(() => {
        progress -= step
        const notif = notifications.value.find(n => n.id === id)
        if (notif) {
          notif.progress = Math.max(0, progress)
        }

        if (progress <= 0) {
          clearInterval(timer)
          removeNotification(id)
        }
      }, interval)

      newNotification.timer = timer
    }

    return id
  }

  const removeNotification = (id: string) => {
    const index = notifications.value.findIndex(n => n.id === id)
    if (index > -1) {
      const notification = notifications.value[index]
      if (notification.timer) {
        clearInterval(notification.timer)
      }
      notification.onClose?.()
      notifications.value.splice(index, 1)
    }
  }

  const executeActionCallback = async (
    callback?: () => void | Promise<void>
  ) => {
    if (!callback) return

    try {
      await callback()
    } catch (error) {
      console.error('Error executing notification action callback:', error)
    }
  }

  const handleAction = async (id: string) => {
    const notification = notifications.value.find(n => n.id === id)
    if (!notification) return

    await executeActionCallback(notification.action?.callback)
    removeNotification(id)
  }

  const clearAll = () => {
    notifications.value.forEach(notification => {
      if (notification.timer) {
        clearInterval(notification.timer)
      }
      notification.onClose?.()
    })
    notifications.value = []
  }

  // Helper methods for common notification types
  const success = (message: string, title?: string, options?: Partial<Notification>) => {
    return addNotification({ type: 'success', message, title, ...options })
  }

  const error = (message: string, title?: string, options?: Partial<Notification>) => {
    return addNotification({
      type: 'error',
      message,
      title,
      autoClose: false, // Errors don't auto-close by default
      ...options
    })
  }

  const warning = (message: string, title?: string, options?: Partial<Notification>) => {
    return addNotification({ type: 'warning', message, title, ...options })
  }

  const info = (message: string, title?: string, options?: Partial<Notification>) => {
    return addNotification({ type: 'info', message, title, ...options })
  }

  return {
    notifications: computed(() => notifications.value),
    addNotification,
    removeNotification,
    handleAction,
    clearAll,
    success,
    error,
    warning,
    info
  }
}

// Global notification instance
export const notify = useNotifications()

import { ref, onMounted, onUnmounted } from 'vue'

export interface PWAUpdateInfo {
  available: boolean
  registration?: ServiceWorkerRegistration
  refreshing: boolean
}

export interface CacheStatus {
  version: string
  caches: Array<{
    name: string
    size: number
    urls: string[]
  }>
}

export const usePWA = () => {
  const isOnline = ref(navigator.onLine)
  const updateAvailable = ref(false)
  const isInstallable = ref(false)
  const isInstalled = ref(false)
  const refreshing = ref(false)
  const registration = ref<ServiceWorkerRegistration | null>(null)
  const installPrompt = ref<BeforeInstallPromptEvent | null>(null)
  const cacheStatus = ref<CacheStatus | null>(null)

  // Interface pour l'événement beforeinstallprompt
  interface BeforeInstallPromptEvent extends Event {
    readonly platforms: string[]
    readonly userChoice: Promise<{
      outcome: 'accepted' | 'dismissed'
      platform: string
    }>
    prompt(): Promise<void>
  }

  // Installer le Service Worker
  const installServiceWorker = async () => {
    if (!('serviceWorker' in navigator)) {
      console.warn('Service Worker not supported')
      return false
    }

    try {
      const reg = await navigator.serviceWorker.register('/sw.js', {
        scope: '/'
      })

      registration.value = reg

      console.log('Service Worker registered successfully:', reg.scope)

      // Écouter les mises à jour
      reg.addEventListener('updatefound', () => {
        const newWorker = reg.installing

        if (newWorker) {
          newWorker.addEventListener('statechange', () => {
            if (newWorker.state === 'installed') {
              if (navigator.serviceWorker.controller) {
                // Nouvelle version disponible
                updateAvailable.value = true
              } else {
                // Premier install
                console.log('Service Worker installed for the first time')
              }
            }
          })
        }
      })

      return true
    } catch (error) {
      console.error('Service Worker registration failed:', error)
      return false
    }
  }

  // Forcer la mise à jour du Service Worker
  const updateServiceWorker = async () => {
    if (!registration.value) return

    refreshing.value = true

    const reg = registration.value
    const waiting = reg.waiting

    if (waiting) {
      // Demander au service worker en attente de prendre le contrôle
      waiting.postMessage({ type: 'SKIP_WAITING' })

      // Attendre que le nouveau service worker prenne le contrôle
      navigator.serviceWorker.addEventListener('controllerchange', () => {
        refreshing.value = false
        window.location.reload()
      })
    }
  }

  // Vérifier si l'app peut être installée
  const checkInstallability = () => {
    // Vérifier si l'app est déjà installée
    if (window.matchMedia('(display-mode: standalone)').matches ||
        (window.navigator as any).standalone === true) {
      isInstalled.value = true
      return
    }

    // Écouter l'événement beforeinstallprompt
    window.addEventListener('beforeinstallprompt', (e: Event) => {
      e.preventDefault()
      installPrompt.value = e as BeforeInstallPromptEvent
      isInstallable.value = true
    })

    // Écouter l'événement appinstalled
    window.addEventListener('appinstalled', () => {
      isInstalled.value = true
      isInstallable.value = false
      installPrompt.value = null
    })
  }

  // Installer l'application PWA
  const installApp = async () => {
    if (!installPrompt.value) return false

    try {
      await installPrompt.value.prompt()
      const choiceResult = await installPrompt.value.userChoice

      if (choiceResult.outcome === 'accepted') {
        console.log('User accepted the install prompt')
        isInstallable.value = false
        installPrompt.value = null
        return true
      } else {
        console.log('User dismissed the install prompt')
        return false
      }
    } catch (error) {
      console.error('Error during app installation:', error)
      return false
    }
  }

  // Gérer la connectivité
  const handleOnline = () => {
    isOnline.value = true
    announceConnectionStatus('Connexion rétablie')
  }

  const handleOffline = () => {
    isOnline.value = false
    announceConnectionStatus('Connexion perdue - Mode hors ligne activé')
  }

  // Annoncer le statut de connexion
  const announceConnectionStatus = (message: string) => {
    if ('serviceWorker' in navigator && navigator.serviceWorker.controller) {
      navigator.serviceWorker.controller.postMessage({
        type: 'ANNOUNCE',
        message
      })
    }
  }

  // Cache des URLs spécifiques
  const cacheUrls = async (urls: string[]) => {
    if ('serviceWorker' in navigator && navigator.serviceWorker.controller) {
      navigator.serviceWorker.controller.postMessage({
        type: 'CACHE_URLS',
        urls
      })
    }
  }

  // Vider le cache
  const clearCache = async () => {
    if ('serviceWorker' in navigator && navigator.serviceWorker.controller) {
      navigator.serviceWorker.controller.postMessage({
        type: 'CLEAR_CACHE'
      })
    }
  }

  // Obtenir le statut du cache
  const getCacheStatus = async (): Promise<CacheStatus | null> => {
    if (!('serviceWorker' in navigator) || !navigator.serviceWorker.controller) {
      return null
    }

    return new Promise((resolve) => {
      const messageChannel = new MessageChannel()

      messageChannel.port1.onmessage = (event) => {
        cacheStatus.value = event.data
        resolve(event.data)
      }

      navigator.serviceWorker.controller?.postMessage(
        { type: 'GET_CACHE_STATUS' },
        [messageChannel.port2]
      )
    })
  }

  // Enregistrer pour la synchronisation en arrière-plan
  const registerBackgroundSync = async (tag: string) => {
    if (!registration.value || !('sync' in window.ServiceWorkerRegistration.prototype)) {
      console.warn('Background sync not supported')
      return false
    }

    try {
      await (registration.value as any).sync.register(tag)
      console.log('Background sync registered:', tag)
      return true
    } catch (error) {
      console.error('Background sync registration failed:', error)
      return false
    }
  }

  // Partager du contenu
  const shareContent = async (shareData: ShareData) => {
    if ('share' in navigator) {
      try {
        await navigator.share(shareData)
        return true
      } catch (error) {
        console.error('Sharing failed:', error)
        return false
      }
    } else {
      // Fallback pour les navigateurs qui ne supportent pas Web Share API
      if (shareData.url && 'clipboard' in navigator) {
        await (navigator as any).clipboard.writeText(shareData.url)
        return true
      }
      return false
    }
  }

  // Détecter le mode d'affichage
  const getDisplayMode = (): string => {
    if (window.matchMedia('(display-mode: standalone)').matches) {
      return 'standalone'
    }
    if (window.matchMedia('(display-mode: minimal-ui)').matches) {
      return 'minimal-ui'
    }
    if (window.matchMedia('(display-mode: fullscreen)').matches) {
      return 'fullscreen'
    }
    return 'browser'
  }

  // Initialiser PWA
  const initializePWA = async () => {
    await installServiceWorker()
    checkInstallability()

    // Obtenir le statut initial du cache
    await getCacheStatus()

    console.log('PWA initialized successfully')
  }

  // Lifecycle
  onMounted(() => {
    // Écouter les changements de connectivité
    window.addEventListener('online', handleOnline)
    window.addEventListener('offline', handleOffline)

    // Initialiser PWA
    initializePWA()
  })

  onUnmounted(() => {
    window.removeEventListener('online', handleOnline)
    window.removeEventListener('offline', handleOffline)
  })

  return {
    // État
    isOnline,
    updateAvailable,
    isInstallable,
    isInstalled,
    refreshing,
    registration,
    cacheStatus,

    // Méthodes Service Worker
    installServiceWorker,
    updateServiceWorker,

    // Méthodes Installation
    installApp,

    // Méthodes Cache
    cacheUrls,
    clearCache,
    getCacheStatus,

    // Méthodes Utilitaires
    registerBackgroundSync,
    shareContent,
    getDisplayMode,

    // Propriétés calculées
    displayMode: getDisplayMode(),
    canShare: 'share' in navigator,
    supportsBackgroundSync: 'serviceWorker' in navigator && 'sync' in window.ServiceWorkerRegistration.prototype
  }
}

import { ref, onMounted, onUnmounted, computed } from 'vue'
import { performanceMonitor, memoryManager } from '@/utils/performance'

export function usePerformance() {
  const metrics = ref({
    fcp: null as number | null,
    lcp: null as number | null,
    fid: null as number | null,
    cls: null as number | null,
    ttfb: null as number | null
  })

  const memory = ref({
    used: 0,
    total: 0,
    limit: 0
  })

  const score = computed(() => performanceMonitor.getScore())

  const updateMetrics = () => {
    metrics.value = performanceMonitor.getMetrics()
    const memoryUsage = memoryManager.getMemoryUsage()
    if (memoryUsage) {
      memory.value = memoryUsage
    }
  }

  onMounted(() => {
    updateMetrics()

    // Update metrics every 5 seconds
    memoryManager.addInterval(updateMetrics, 5000)

    // Update on key performance events
    window.addEventListener('load', updateMetrics)

    memoryManager.addCleanup(() => {
      window.removeEventListener('load', updateMetrics)
    })
  })

  return {
    metrics: computed(() => metrics.value),
    memory: computed(() => memory.value),
    score,
    updateMetrics
  }
}

export function useMemoryOptimization() {
  const cleanup = ref<(() => void)[]>([])

  const addCleanup = (fn: () => void) => {
    cleanup.value.push(fn)
    memoryManager.addCleanup(fn)
  }

  const addInterval = (fn: () => void, delay: number) => {
    return memoryManager.addInterval(fn, delay)
  }

  const addTimeout = (fn: () => void, delay: number) => {
    return memoryManager.addTimeout(fn, delay)
  }

  onUnmounted(() => {
    cleanup.value.forEach(fn => fn())
    cleanup.value = []
  })

  return {
    addCleanup,
    addInterval,
    addTimeout
  }
}

// Virtual scrolling for large lists
export function useVirtualScrolling(items: any[], itemHeight: number = 50) {
  const containerRef = ref<HTMLElement>()
  const scrollTop = ref(0)
  const containerHeight = ref(0)

  const visibleItems = computed(() => {
    const start = Math.floor(scrollTop.value / itemHeight)
    const end = Math.min(
      start + Math.ceil(containerHeight.value / itemHeight) + 1,
      items.length
    )

    return {
      start,
      end,
      items: items.slice(start, end),
      offsetY: start * itemHeight,
      totalHeight: items.length * itemHeight
    }
  })

  const onScroll = (event: Event) => {
    const target = event.target as HTMLElement
    scrollTop.value = target.scrollTop
  }

  onMounted(() => {
    if (containerRef.value) {
      containerHeight.value = containerRef.value.clientHeight

      const resizeObserver = new ResizeObserver(() => {
        if (containerRef.value) {
          containerHeight.value = containerRef.value.clientHeight
        }
      })

      resizeObserver.observe(containerRef.value)

      memoryManager.addCleanup(() => {
        resizeObserver.disconnect()
      })
    }
  })

  return {
    containerRef,
    visibleItems,
    onScroll
  }
}

// Debounced search for better performance
export function useDebouncedSearch(delay: number = 300) {
  const searchTerm = ref('')
  const debouncedSearchTerm = ref('')
  let timeoutId: NodeJS.Timeout | null = null

  const updateDebouncedSearch = (value: string) => {
    searchTerm.value = value

    if (timeoutId) {
      clearTimeout(timeoutId)
    }

    timeoutId = setTimeout(() => {
      debouncedSearchTerm.value = value
    }, delay)
  }

  onUnmounted(() => {
    if (timeoutId) {
      clearTimeout(timeoutId)
    }
  })

  return {
    searchTerm,
    debouncedSearchTerm: computed(() => debouncedSearchTerm.value),
    updateSearch: updateDebouncedSearch
  }
}

// Image lazy loading composable
export function useImageLazyLoading() {
  const imageRef = ref<HTMLImageElement>()
  const isLoaded = ref(false)
  const isError = ref(false)

  onMounted(() => {
    if (imageRef.value && 'IntersectionObserver' in window) {
      const observer = new IntersectionObserver(
        (entries) => {
          entries.forEach((entry) => {
            if (entry.isIntersecting && imageRef.value) {
              const img = imageRef.value
              const src = img.dataset.src

              if (src) {
                img.src = src
                img.onload = () => {
                  isLoaded.value = true
                  observer.unobserve(img)
                }
                img.onerror = () => {
                  isError.value = true
                  observer.unobserve(img)
                }
              }
            }
          })
        },
        {
          rootMargin: '50px 0px',
          threshold: 0.1
        }
      )

      observer.observe(imageRef.value)

      memoryManager.addCleanup(() => {
        observer.disconnect()
      })
    }
  })

  return {
    imageRef,
    isLoaded: computed(() => isLoaded.value),
    isError: computed(() => isError.value)
  }
}

