import { api, apiEndpoints, type ApiResponse } from './apiClient'

export interface ServerNotification {
  id: number
  user_id: number
  type: string | null
  title: string
  message: string
  is_read: boolean
  sent_via?: string | null
  sent_at?: string | null
  created_at?: string | null
}

interface NotificationListResponse {
  success: boolean
  data: ServerNotification[]
  meta: {
    current_page: number
    last_page: number
    per_page: number
    total: number
  }
}

interface PreferencesResponse extends ApiResponse<{
  prefers_email_notifications: boolean
  prefers_sms_notifications: boolean
  prefers_push_notifications: boolean
}> {}

const vapidPublicKey = (import.meta.env.VITE_VAPID_PUBLIC_KEY || '') as string

function urlBase64ToUint8Array(base64String: string): Uint8Array {
  const padding = '='.repeat((4 - (base64String.length % 4)) % 4)
  const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/')

  const rawData = window.atob(base64)
  const outputArray = new Uint8Array(rawData.length)

  for (let i = 0; i < rawData.length; ++i) {
    outputArray[i] = rawData.charCodeAt(i)
  }
  return outputArray
}

export async function fetchNotifications(options: { unread?: boolean; page?: number; perPage?: number } = {}): Promise<NotificationListResponse> {
  const params = new URLSearchParams()

  if (options.unread) params.append('unread', '1')
  if (options.page) params.append('page', options.page.toString())
  if (options.perPage) params.append('per_page', options.perPage.toString())

  const query = params.toString()
  const endpoint = query ? `${apiEndpoints.notifications}?${query}` : apiEndpoints.notifications

  return api.get<NotificationListResponse>(endpoint)
}

export function markNotificationAsRead(id: number) {
  return api.post<ApiResponse<ServerNotification>>(apiEndpoints.notificationRead(id))
}

export function markAllNotificationsAsRead() {
  return api.post<ApiResponse<null>>(apiEndpoints.notificationsReadAll)
}

export function updateNotificationPreferences(preferences: { email: boolean; sms: boolean; push: boolean }) {
  return api.patch<PreferencesResponse>(apiEndpoints.notificationPreferences, preferences)
}

export async function subscribeToPush(): Promise<PushSubscription | null> {
  if (!('serviceWorker' in navigator) || !('PushManager' in window)) {
    return null
  }

  if (!vapidPublicKey) {
    console.warn('Missing VAPID public key for push subscriptions')
    return null
  }

  const permission = await Notification.requestPermission()
  if (permission !== 'granted') {
    return null
  }

  const registration = await navigator.serviceWorker.ready
  let subscription = await registration.pushManager.getSubscription()

  if (!subscription) {
    subscription = await registration.pushManager.subscribe({
      userVisibleOnly: true,
      applicationServerKey: urlBase64ToUint8Array(vapidPublicKey) as BufferSource
    })
  }

  const subscriptionData = subscription.toJSON()

  await api.post(apiEndpoints.notificationSubscriptions, {
    endpoint: subscriptionData.endpoint,
    public_key: subscriptionData.keys?.p256dh,
    auth_token: subscriptionData.keys?.auth,
    content_encoding: 'aes128gcm'
  })

  return subscription
}

export async function unsubscribeFromPush(): Promise<boolean> {
  if (!('serviceWorker' in navigator)) {
    return false
  }

  const registration = await navigator.serviceWorker.ready
  const subscription = await registration.pushManager.getSubscription()

  if (!subscription) {
    return false
  }

  const endpoint = subscription.endpoint
  await subscription.unsubscribe()
  await api.delete(`${apiEndpoints.notificationSubscriptions}?endpoint=${encodeURIComponent(endpoint)}`)

  return true
}

/**
 * WebSocket Service
 * Handles real-time communication for messaging, notifications, and live updates
 */

import { ref, computed } from 'vue'
import { useAuthStore } from '@/stores/auth'

export type WebSocketStatus = 'disconnected' | 'connecting' | 'connected' | 'error' | 'reconnecting'

export interface WebSocketMessage {
  type: string
  channel?: string
  data?: any
  timestamp?: string
}

export interface ChannelSubscription {
  channel: string
  callback: (data: any) => void
}

class WebSocketService {
  private socket: WebSocket | null = null
  private reconnectAttempts = 0
  private maxReconnectAttempts = 5
  private reconnectDelay = 1000
  private heartbeatInterval: ReturnType<typeof setInterval> | null = null
  private subscriptions: Map<string, Set<(data: any) => void>> = new Map()

  public status = ref<WebSocketStatus>('disconnected')
  public isConnected = computed(() => this.status.value === 'connected')
  public lastError = ref<string | null>(null)

  private wsUrl: string

  constructor() {
    // Determine WebSocket URL based on environment
    const apiUrl = import.meta.env.VITE_API_URL || 'https://antigaspi.jubtek.com'
    const wsProtocol = apiUrl.startsWith('https') ? 'wss' : 'ws'
    const wsHost = apiUrl.replace(/^https?:\/\//, '').replace(/\/api$/, '')
    this.wsUrl = `${wsProtocol}://${wsHost}/ws`
  }

  /**
   * Connect to WebSocket server
   */
  connect(): Promise<void> {
    return new Promise((resolve, reject) => {
      if (this.socket?.readyState === WebSocket.OPEN) {
        resolve()
        return
      }

      const authStore = useAuthStore()
      if (!authStore.token) {
        this.lastError.value = 'Authentication required'
        reject(new Error('Authentication required'))
        return
      }

      this.status.value = 'connecting'
      this.lastError.value = null

      try {
        // Include token in connection
        const url = `${this.wsUrl}?token=${encodeURIComponent(authStore.token)}`
        this.socket = new WebSocket(url)

        this.socket.onopen = () => {
          this.status.value = 'connected'
          this.reconnectAttempts = 0
          this.startHeartbeat()
          this.resubscribeAll()
          resolve()
        }

        this.socket.onmessage = (event) => {
          this.handleMessage(event.data)
        }

        this.socket.onerror = (error) => {
          console.error('WebSocket error:', error)
          this.status.value = 'error'
          this.lastError.value = 'Connection error'
        }

        this.socket.onclose = (event) => {
          this.stopHeartbeat()
          this.status.value = 'disconnected'

          if (!event.wasClean && this.reconnectAttempts < this.maxReconnectAttempts) {
            this.scheduleReconnect()
          }
        }
      } catch (error) {
        this.status.value = 'error'
        this.lastError.value = 'Failed to create WebSocket connection'
        reject(error)
      }
    })
  }

  /**
   * Disconnect from WebSocket server
   */
  disconnect(): void {
    this.stopHeartbeat()

    if (this.socket) {
      this.socket.close(1000, 'Client disconnect')
      this.socket = null
    }

    this.status.value = 'disconnected'
    this.reconnectAttempts = 0
  }

  /**
   * Send a message through WebSocket
   */
  send(type: string, data?: any, channel?: string): boolean {
    if (!this.socket || this.socket.readyState !== WebSocket.OPEN) {
      console.warn('WebSocket not connected, cannot send message')
      return false
    }

    const message: WebSocketMessage = {
      type,
      channel,
      data,
      timestamp: new Date().toISOString()
    }

    try {
      this.socket.send(JSON.stringify(message))
      return true
    } catch (error) {
      console.error('Failed to send WebSocket message:', error)
      return false
    }
  }

  /**
   * Subscribe to a channel
   */
  subscribe(channel: string, callback: (data: any) => void): () => void {
    if (!this.subscriptions.has(channel)) {
      this.subscriptions.set(channel, new Set())
    }

    this.subscriptions.get(channel)!.add(callback)

    // Send subscription request to server
    if (this.isConnected.value) {
      this.send('subscribe', { channel })
    }

    // Return unsubscribe function
    return () => {
      this.unsubscribe(channel, callback)
    }
  }

  /**
   * Unsubscribe from a channel
   */
  unsubscribe(channel: string, callback: (data: any) => void): void {
    const callbacks = this.subscriptions.get(channel)
    if (callbacks) {
      callbacks.delete(callback)

      if (callbacks.size === 0) {
        this.subscriptions.delete(channel)
        // Notify server
        if (this.isConnected.value) {
          this.send('unsubscribe', { channel })
        }
      }
    }
  }

  /**
   * Subscribe to user-specific channel
   */
  subscribeToUser(userId: number, callback: (data: any) => void): () => void {
    return this.subscribe(`user.${userId}`, callback)
  }

  /**
   * Subscribe to conversation messages
   */
  subscribeToConversation(conversationId: number, callback: (data: any) => void): () => void {
    return this.subscribe(`conversation.${conversationId}`, callback)
  }

  /**
   * Subscribe to notifications
   */
  subscribeToNotifications(callback: (data: any) => void): () => void {
    const authStore = useAuthStore()
    if (!authStore.user?.id) {
      console.warn('User not authenticated, cannot subscribe to notifications')
      return () => {}
    }
    return this.subscribe(`notifications.${authStore.user.id}`, callback)
  }

  /**
   * Subscribe to order/reservation updates
   */
  subscribeToReservation(reservationId: number, callback: (data: any) => void): () => void {
    return this.subscribe(`reservation.${reservationId}`, callback)
  }

  /**
   * Subscribe to wallet updates
   */
  subscribeToWallet(callback: (data: any) => void): () => void {
    const authStore = useAuthStore()
    if (!authStore.user?.id) {
      console.warn('User not authenticated, cannot subscribe to wallet')
      return () => {}
    }
    return this.subscribe(`wallet.${authStore.user.id}`, callback)
  }

  /**
   * Handle incoming WebSocket message
   */
  private handleMessage(rawData: string): void {
    try {
      const message: WebSocketMessage = JSON.parse(rawData)

      // Handle system messages
      if (message.type === 'ping') {
        this.send('pong')
        return
      }

      if (message.type === 'error') {
        console.error('WebSocket server error:', message.data)
        return
      }

      // Route message to channel subscribers
      if (message.channel && message.type === 'message') {
        const callbacks = this.subscriptions.get(message.channel)
        if (callbacks) {
          callbacks.forEach(callback => {
            try {
              callback(message.data)
            } catch (error) {
              console.error('Error in WebSocket callback:', error)
            }
          })
        }
      }

      // Emit generic event
      this.emitEvent(message.type, message.data)
    } catch (error) {
      console.error('Failed to parse WebSocket message:', error)
    }
  }

  /**
   * Emit event to all listeners
   */
  private eventListeners: Map<string, Set<(data: any) => void>> = new Map()

  on(event: string, callback: (data: any) => void): () => void {
    if (!this.eventListeners.has(event)) {
      this.eventListeners.set(event, new Set())
    }

    this.eventListeners.get(event)!.add(callback)

    return () => {
      this.off(event, callback)
    }
  }

  off(event: string, callback: (data: any) => void): void {
    const listeners = this.eventListeners.get(event)
    if (listeners) {
      listeners.delete(callback)
    }
  }

  private emitEvent(event: string, data: any): void {
    const listeners = this.eventListeners.get(event)
    if (listeners) {
      listeners.forEach(callback => {
        try {
          callback(data)
        } catch (error) {
          console.error(`Error in event listener for ${event}:`, error)
        }
      })
    }
  }

  /**
   * Schedule reconnection attempt
   */
  private scheduleReconnect(): void {
    this.status.value = 'reconnecting'
    this.reconnectAttempts++

    const delay = this.reconnectDelay * Math.pow(2, this.reconnectAttempts - 1)
    console.log(`WebSocket reconnecting in ${delay}ms (attempt ${this.reconnectAttempts})`)

    setTimeout(() => {
      if (this.status.value === 'reconnecting') {
        this.connect().catch(error => {
          console.error('Reconnection failed:', error)
        })
      }
    }, delay)
  }

  /**
   * Resubscribe to all channels after reconnection
   */
  private resubscribeAll(): void {
    for (const channel of this.subscriptions.keys()) {
      this.send('subscribe', { channel })
    }
  }

  /**
   * Start heartbeat to keep connection alive
   */
  private startHeartbeat(): void {
    this.stopHeartbeat()
    this.heartbeatInterval = setInterval(() => {
      if (this.isConnected.value) {
        this.send('ping')
      }
    }, 30000) // Every 30 seconds
  }

  /**
   * Stop heartbeat
   */
  private stopHeartbeat(): void {
    if (this.heartbeatInterval) {
      clearInterval(this.heartbeatInterval)
      this.heartbeatInterval = null
    }
  }

  /**
   * Get connection status
   */
  getStatus(): WebSocketStatus {
    return this.status.value
  }

  /**
   * Check if connected
   */
  isReady(): boolean {
    return this.isConnected.value
  }
}

// Export singleton instance
export const websocketService = new WebSocketService()

// Vue composable for using WebSocket in components
export function useWebSocket() {
  const connect = () => websocketService.connect()
  const disconnect = () => websocketService.disconnect()
  const send = (type: string, data?: any, channel?: string) => websocketService.send(type, data, channel)
  const subscribe = (channel: string, callback: (data: any) => void) => websocketService.subscribe(channel, callback)
  const on = (event: string, callback: (data: any) => void) => websocketService.on(event, callback)

  return {
    status: websocketService.status,
    isConnected: websocketService.isConnected,
    lastError: websocketService.lastError,
    connect,
    disconnect,
    send,
    subscribe,
    on,
    subscribeToConversation: websocketService.subscribeToConversation.bind(websocketService),
    subscribeToNotifications: websocketService.subscribeToNotifications.bind(websocketService),
    subscribeToReservation: websocketService.subscribeToReservation.bind(websocketService),
    subscribeToWallet: websocketService.subscribeToWallet.bind(websocketService)
  }
}

import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import type { User, LoginCredentials, RegisterData } from '@/types'
import { apiService } from '@/services/api'
import { deviceService } from '@/services/deviceService'
import { notify } from '@/composables/useNotifications'

export const useAuthStore = defineStore('auth', () => {
  const user = ref<User | null>(null)
  const token = ref<string | null>(localStorage.getItem('auth_token'))
  const loading = ref(false)
  // error ref removed - using useNotifications composable

  // Initialize user from localStorage if available
  const initUser = () => {
    const savedUser = localStorage.getItem('user')
    if (savedUser && token.value) {
      try {
        user.value = JSON.parse(savedUser)
      } catch (err) {
        console.error('Error parsing saved user data:', err)
        localStorage.removeItem('user')
      }
    }
  }

  // Initialize on store creation
  initUser()

  const isAuthenticated = computed(() => !!token.value && !!user.value)
  const isConsumer = computed(() => user.value?.role === 'consumer')
  const isMerchant = computed(() => user.value?.role === 'merchant')
  const isAdmin = computed(() => user.value?.role === 'admin')
  const isDriver = computed(() => user.value?.role === 'driver')

  // setError removed - using useNotifications composable

  // clearError removed - using useNotifications composable

  const persistUser = (userData: User | null) => {
    if (userData) {
      localStorage.setItem('user', JSON.stringify(userData))
    } else {
      localStorage.removeItem('user')
    }
  }

  const setUser = (userData: User | null) => {
    user.value = userData
    persistUser(userData)
  }

  const updateStoredUser = (updates: Partial<User>) => {
    if (!user.value) {
      return null
    }

    const updatedUser = { ...user.value, ...updates }
    setUser(updatedUser)
    return updatedUser
  }

  const setAuth = (authToken: string, userData: User) => {
    token.value = authToken
    setUser(userData)
    localStorage.setItem('auth_token', authToken)
  }

  const clearAuth = () => {
    token.value = null
    setUser(null)
    localStorage.removeItem('auth_token')
  }

  const login = async (credentials: LoginCredentials) => {
    try {
      loading.value = true

      const response = await apiService.login(credentials)

      setAuth(response.data.token, response.data.user)
      notify.success('Connexion réussie', 'Authentification')

      return { success: true }
    } catch (err: any) {
      notify.error(err.message || 'Erreur de connexion', 'Authentification', {
        action: {
          label: 'Réessayer',
          callback: () => { login(credentials) }
        }
      })
      return { success: false, error: err.message }
    } finally {
      loading.value = false
    }
  }

  const register = async (data: RegisterData) => {
    try {
      loading.value = true

      const response = await apiService.register(data)

      setAuth(response.data.token, response.data.user)
      notify.success('Inscription réussie', 'Bienvenue !')

      return { success: true }
    } catch (err: any) {
      notify.error(err.message || 'Erreur d\'inscription', 'Inscription', {
        action: {
          label: 'Réessayer',
          callback: () => { register(data) }
        }
      })
      return { success: false, error: err.message }
    } finally {
      loading.value = false
    }
  }

  const logout = async () => {
    try {
      loading.value = true

      if (token.value) {
        try {
          // Call both legacy logout and device logout
          await Promise.allSettled([
            apiService.logout(),
            deviceService.logout()
          ])
        } catch (err: any) {
          // Ignore logout API errors - token will be cleared locally anyway
          // This can happen if token is already expired or invalid
        }
      }
    } finally {
      clearAuth()
      notify.info('Vous avez \u00e9t\u00e9 d\u00e9connect\u00e9', 'Au revoir !')
      loading.value = false
    }
  }

  const getCurrentUser = async () => {
    if (!token.value) return

    try {
      loading.value = true
      const response = await apiService.getCurrentUser()
      setUser(response.data)
    } catch (err: any) {
      console.error('Failed to get current user:', err.message)
      notify.error('Session expir\u00e9e, veuillez vous reconnecter', 'Authentification')
      clearAuth()
    } finally {
      loading.value = false
    }
  }

  const initAuth = async () => {
    if (token.value && !user.value) {
      await getCurrentUser()
    }
  }

  return {
    // State
    user,
    token,
    loading,

    // Getters
    isAuthenticated,
    isConsumer,
    isMerchant,
    isAdmin,
    isDriver,

    // Actions
    login,
    register,
    logout,
    getCurrentUser,
    initAuth,
    setUser,
    updateStoredUser,
    setAuth
  }
})

import { defineStore } from 'pinia'
import { ref } from 'vue'
import { driverService } from '@/services/driverService'
import { notify } from '@/composables/useNotifications'
import type { Delivery, DeliveryDriverProfile, DriverStats, DriverEarning } from '@/types'

export const useDriverStore = defineStore('driver', () => {
  const profile = ref<DeliveryDriverProfile | null>(null)
  const stats = ref<DriverStats | null>(null)
  const availableDeliveries = ref<Delivery[]>([])
  const activeDelivery = ref<Delivery | null>(null)
  const history = ref<Delivery[]>([])
  const historyPagination = ref<Record<string, number> | null>(null)
  const earnings = ref<DriverEarning[]>([])
  const earningsSummary = ref<Record<string, number>>({})
  const earningsPagination = ref<Record<string, number> | null>(null)
  const loading = ref(false)
  const error = ref<string | null>(null)

  const setError = (message: string) => {
    error.value = message
  }

  const clearError = () => {
    error.value = null
  }

  const normalizePaginated = <T>(payload: any) => {
    if (Array.isArray(payload)) {
      return { items: payload as T[], meta: null }
    }

    const items = Array.isArray(payload?.data) ? (payload.data as T[]) : []
    const meta = payload && typeof payload === 'object'
      ? {
        current_page: payload.current_page ?? payload.currentPage,
        last_page: payload.last_page ?? payload.lastPage,
        per_page: payload.per_page ?? payload.perPage,
        total: payload.total
      }
      : null

    return { items, meta }
  }

  const fetchProfile = async () => {
    loading.value = true
    clearError()
    try {
      const response = await driverService.getProfile()
      profile.value = response.data.driver
      stats.value = response.data.stats
      return true
    } catch (err: any) {
      const message = err?.message || 'Impossible de charger le profil livreur'
      setError(message)
      notify.error(message)
      return false
    } finally {
      loading.value = false
    }
  }

  const toggleAvailability = async () => {
    loading.value = true
    clearError()
    try {
      const response = await driverService.toggleAvailability()
      if (profile.value) {
        profile.value.is_available = response.data.is_available
      }
      notify.success(response.message || 'Statut mis à jour')
      return response.data
    } catch (err: any) {
      const message = err?.message || 'Impossible de changer votre statut'
      setError(message)
      notify.error(message)
      return null
    } finally {
      loading.value = false
    }
  }

  const updateLocation = async (latitude: number, longitude: number) => {
    try {
      const response = await driverService.updateLocation({ latitude, longitude })
      if (profile.value) {
        profile.value.current_latitude = response.data.latitude
        profile.value.current_longitude = response.data.longitude
        profile.value.last_location_update = response.data.updated_at
      }
      return response.data
    } catch (err: any) {
      const message = err?.message || 'Impossible de mettre à jour la position'
      setError(message)
      return null
    }
  }

  const fetchAvailableDeliveries = async () => {
    loading.value = true
    clearError()
    try {
      const response = await driverService.getAvailableDeliveries()
      availableDeliveries.value = response.data || []
      return true
    } catch (err: any) {
      const message = err?.message || 'Impossible de charger les livraisons disponibles'
      setError(message)
      return false
    } finally {
      loading.value = false
    }
  }

  const fetchActiveDelivery = async () => {
    loading.value = true
    clearError()
    try {
      const response = await driverService.getActiveDelivery()
      activeDelivery.value = response.data || null
      return true
    } catch (err: any) {
      const message = err?.message || 'Impossible de charger la livraison en cours'
      setError(message)
      return false
    } finally {
      loading.value = false
    }
  }

  const fetchHistory = async () => {
    loading.value = true
    clearError()
    try {
      const response = await driverService.getDeliveryHistory()
      const { items, meta } = normalizePaginated<Delivery>(response.data)
      history.value = items
      historyPagination.value = meta
      return true
    } catch (err: any) {
      const message = err?.message || 'Impossible de charger l’historique'
      setError(message)
      return false
    } finally {
      loading.value = false
    }
  }

  const fetchEarnings = async (period = 'month') => {
    loading.value = true
    clearError()
    try {
      const response = await driverService.getEarnings({ period })
      const payload = response.data?.earnings ?? response.data
      const { items, meta } = normalizePaginated<DriverEarning>(payload)
      earnings.value = items
      earningsPagination.value = meta
      earningsSummary.value = response.data?.summary || {}
      return true
    } catch (err: any) {
      const message = err?.message || 'Impossible de charger les gains'
      setError(message)
      return false
    } finally {
      loading.value = false
    }
  }

  const acceptDelivery = async (deliveryId: number) => {
    loading.value = true
    clearError()
    try {
      const response = await driverService.acceptDelivery(deliveryId)
      activeDelivery.value = response.data
      await fetchAvailableDeliveries()
      notify.success('Livraison acceptée')
      return response.data
    } catch (err: any) {
      const message = err?.message || 'Impossible d’accepter la livraison'
      setError(message)
      notify.error(message)
      return null
    } finally {
      loading.value = false
    }
  }

  const rejectDelivery = async (deliveryId: number, reason?: string) => {
    loading.value = true
    clearError()
    try {
      const response = await driverService.rejectDelivery(deliveryId, reason)
      await fetchAvailableDeliveries()
      notify.info('Livraison refusée')
      return response.data
    } catch (err: any) {
      const message = err?.message || 'Impossible de refuser la livraison'
      setError(message)
      notify.error(message)
      return null
    } finally {
      loading.value = false
    }
  }

  const startPickup = async (deliveryId: number) => {
    return driverService.startPickup(deliveryId)
  }

  const confirmPickup = async (deliveryId: number) => {
    return driverService.confirmPickup(deliveryId)
  }

  const startDelivery = async (deliveryId: number) => {
    return driverService.startDelivery(deliveryId)
  }

  const completeDelivery = async (deliveryId: number, payload?: { notes?: string; photo_url?: string; signature_url?: string }) => {
    return driverService.completeDelivery(deliveryId, payload)
  }

  const reportFailure = async (deliveryId: number, reason: string) => {
    return driverService.reportFailure(deliveryId, reason)
  }

  const cancelDelivery = async (deliveryId: number, reason: string) => {
    return driverService.cancelDelivery(deliveryId, reason)
  }

  return {
    profile,
    stats,
    availableDeliveries,
    activeDelivery,
    history,
    historyPagination,
    earnings,
    earningsSummary,
    earningsPagination,
    loading,
    error,
    fetchProfile,
    toggleAvailability,
    updateLocation,
    fetchAvailableDeliveries,
    fetchActiveDelivery,
    fetchHistory,
    fetchEarnings,
    acceptDelivery,
    rejectDelivery,
    startPickup,
    confirmPickup,
    startDelivery,
    completeDelivery,
    reportFailure,
    cancelDelivery,
    cancelDeliveryDirect: cancelDelivery
  }
})

import { defineStore } from 'pinia'
import { computed, ref, watch } from 'vue'
import type { Category, Merchant, Product, FavoriteProductSummary } from '@/types'
import { apiService } from '@/services/api'
import { notify, type Notification } from '@/composables/useNotifications'

export type FavoriteType = 'product' | 'merchant'

export interface FavoriteItem {
  id: number
  type: FavoriteType
  name: string
  description?: string | null
  imageUrl?: string | null
  merchant?: Partial<Merchant> | null
  product?: Partial<Product> | null
  tags?: string[]
  addedAt: string
}

interface FavoritesNotificationPayload {
  title?: string
  message: string
  action?: Notification['action']
  onClose?: Notification['onClose']
  operation?: string
}

const MERCHANT_STORAGE_KEY = 'antigaspi_favorite_merchants'

const parseMerchantStorage = (raw: string | null): FavoriteItem[] => {
  if (!raw) {
    return []
  }

  try {
    const parsed = JSON.parse(raw)
    if (!Array.isArray(parsed)) {
      return []
    }

    return parsed
      .filter(item => item && item.type === 'merchant')
      .map(item => ({
        id: Number(item.id),
        type: 'merchant' as const,
        name: item.name ?? 'Commerçant AntiGaspi',
        description: item.description ?? null,
        imageUrl: item.imageUrl ?? null,
        merchant: item.merchant ?? null,
        product: null,
        tags: item.tags ?? [],
        addedAt: item.addedAt ?? new Date().toISOString()
      }))
  } catch (error) {
    console.warn('Unable to parse merchant favorites from storage', error)
    return []
  }
}

const mapProductFavorite = (favorite: FavoriteProductSummary): FavoriteItem => {
  const addedAt = favorite.favorited_at ?? new Date().toISOString()

  const merchant: Partial<Merchant> | null = favorite.merchant
    ? {
      id: Number(favorite.merchant.id ?? 0),
      business_name: favorite.merchant.business_name ?? 'Commerçant AntiGaspi',
      business_type: favorite.merchant.business_type,
      city: favorite.merchant.city,
      address: favorite.merchant.address,
      phone: favorite.merchant.phone,
      is_verified: Boolean((favorite.merchant as any).is_verified)
    }
    : null

  const product: Partial<Product> = {
    id: Number(favorite.id),
    name: favorite.name,
    description: favorite.description ?? '',
    original_price: String(favorite.original_price ?? 0),
    discounted_price: String(favorite.discounted_price ?? 0),
    quantity_available: favorite.quantity_available ?? 0,
    expiration_date: favorite.expiration_date ?? '',
    image_url: favorite.image_url ?? undefined,
    discount_percentage: favorite.discount_percentage ?? 0,
    savings: (favorite.original_price ?? 0) - (favorite.discounted_price ?? 0),
    days_until_expiration: 0,
    category: (favorite.category as Category | undefined) ?? undefined,
    merchant: merchant as any,
    created_at: addedAt
  }

  return {
    id: Number(favorite.id),
    type: 'product',
    name: favorite.name,
    description: favorite.description ?? null,
    imageUrl: favorite.image_url ?? null,
    merchant,
    product,
    tags: [],
    addedAt
  }
}

export const useFavoritesStore = defineStore('favorites', () => {
  const productFavorites = ref<FavoriteItem[]>([])
  const merchantFavorites = ref<FavoriteItem[]>([])
  const favoriteProductIds = ref<Set<number>>(new Set())
  const loading = ref(false)
  const pendingOperation = ref<string | null>(null)
  const initialized = ref(false)
  const merchantsHydrated = ref(false)

  const items = computed(() => {
    const combined = [...productFavorites.value, ...merchantFavorites.value]
    return combined.sort((a, b) => new Date(b.addedAt).getTime() - new Date(a.addedAt).getTime())
  })

  const favoritesCount = computed(() => items.value.length)
  const hasFavorites = computed(() => items.value.length > 0)

  const groupedFavorites = computed(() => {
    return items.value.reduce(
      (groups, item) => {
        groups[item.type].push(item)
        return groups
      },
      { product: [] as FavoriteItem[], merchant: [] as FavoriteItem[] }
    )
  })

  const emitFavoritesNotification = (
    type: 'error' | 'info' | 'success',
    payload: FavoritesNotificationPayload
  ) => {
    const { title = 'Favoris', message, action, onClose, operation } = payload

    if (type === 'error' && operation) {
      pendingOperation.value = operation
    } else if (type !== 'error') {
      pendingOperation.value = null
    }

    const wrappedAction = action
      ? {
        label: action.label,
        callback: async () => {
          await action.callback()
          if (operation && pendingOperation.value === operation) {
            pendingOperation.value = null
          }
        }
      }
      : undefined

    const wrappedOnClose = () => {
      if (operation && pendingOperation.value === operation) {
        pendingOperation.value = null
      }
      onClose?.()
    }

    const options: Partial<Notification> = {
      action: wrappedAction,
      onClose: wrappedOnClose
    }

    if (type === 'error') {
      return notify.error(message, title, options)
    }

    if (type === 'info') {
      return notify.info(message, title, options)
    }

    return notify.success(message, title, options)
  }

  const emitFavoritesError = (payload: FavoritesNotificationPayload) =>
    emitFavoritesNotification('error', payload)
  const emitFavoritesInfo = (payload: FavoritesNotificationPayload) =>
    emitFavoritesNotification('info', payload)
  const emitFavoritesSuccess = (payload: FavoritesNotificationPayload) =>
    emitFavoritesNotification('success', payload)

  const loadMerchantFavorites = () => {
    if (merchantsHydrated.value || typeof window === 'undefined') {
      return
    }

    merchantFavorites.value = parseMerchantStorage(window.localStorage.getItem(MERCHANT_STORAGE_KEY))
    merchantsHydrated.value = true
  }

  const persistMerchantFavorites = () => {
    if (!merchantsHydrated.value || typeof window === 'undefined') {
      return
    }

    try {
      window.localStorage.setItem(MERCHANT_STORAGE_KEY, JSON.stringify(merchantFavorites.value))
    } catch (error) {
      emitFavoritesError({
        message: 'Impossible de sauvegarder vos commerçants favoris',
        operation: 'persist-merchants',
        action: {
          label: 'Réessayer',
          callback: () => persistMerchantFavorites()
        }
      })
    }
  }

  watch(merchantFavorites, persistMerchantFavorites, { deep: true })

  const setProductFavorites = (favorites: FavoriteItem[]) => {
    productFavorites.value = favorites
    favoriteProductIds.value = new Set(favorites.map(favorite => favorite.id))
  }

  const fetchProductFavorites = async () => {
    try {
      loading.value = true
      const response = await apiService.getFavoriteProducts()

      if (!response.success) {
        throw new Error(response.message || 'Erreur lors du chargement des favoris')
      }

      const list = Array.isArray(response.data) ? response.data : []
      setProductFavorites(list.map(mapProductFavorite))
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Erreur lors du chargement des favoris'
      emitFavoritesError({
        message,
        operation: 'fetch-products',
        action: {
          label: 'Réessayer',
          callback: async () => {
            await fetchProductFavorites()
          }
        }
      })
    } finally {
      loading.value = false
    }
  }

  const ensureInitialized = async () => {
    if (!merchantsHydrated.value) {
      loadMerchantFavorites()
    }

    if (!initialized.value) {
      await fetchProductFavorites()
      initialized.value = true
    }
  }

  const findMerchantIndex = (id: number) => merchantFavorites.value.findIndex(item => item.id === id)

  const addMerchantFavorite = (payload: Omit<FavoriteItem, 'addedAt' | 'type'>) => {
    const index = findMerchantIndex(payload.id)
    if (index !== -1) {
      emitFavoritesInfo({ message: 'Ce commerçant est déjà dans vos favoris' })
      return { success: false as const, reason: 'already_exists' as const }
    }

    const favorite: FavoriteItem = {
      ...payload,
      type: 'merchant',
      addedAt: new Date().toISOString()
    }

    merchantFavorites.value = [favorite, ...merchantFavorites.value]
    emitFavoritesSuccess({ message: 'Commerçant ajouté à vos favoris' })
    return { success: true as const, data: favorite }
  }

  const removeMerchantFavorite = (id: number) => {
    const index = findMerchantIndex(id)
    if (index === -1) {
      return { success: false as const, reason: 'not_found' as const }
    }

    const [removed] = merchantFavorites.value.splice(index, 1)
    emitFavoritesInfo({ message: `${removed.name} retiré de vos favoris` })
    return { success: true as const }
  }

  const buildFavoriteFromPayload = async (payload: Omit<FavoriteItem, 'addedAt'>) => {
    if (payload.product) {
      const summary: FavoriteProductSummary = {
        id: payload.id,
        name: payload.name,
        description: payload.description ?? null,
        original_price: Number(payload.product.original_price ?? payload.product.discounted_price ?? 0),
        discounted_price: Number(payload.product.discounted_price ?? payload.product.original_price ?? 0),
        discount_percentage: (payload.product as any)?.discount_percentage ?? undefined,
        quantity_available: Number(payload.product.quantity_available ?? 0),
        expiration_date: payload.product.expiration_date ?? undefined,
        image_url: payload.product.image_url ?? undefined,
        is_active: payload.product.is_active,
        favorited_at: new Date().toISOString(),
        category: payload.product.category ?? undefined,
        merchant: payload.merchant ?? undefined
      }

      return mapProductFavorite(summary)
    }

    try {
      const response = await apiService.getProduct(payload.id)
      if (!response.success) {
        throw new Error(response.message || 'Produit introuvable')
      }

      return mapProductFavorite({
        id: response.data.id,
        name: response.data.name,
        description: response.data.description,
        original_price: Number(response.data.original_price ?? 0),
        discounted_price: Number(response.data.discounted_price ?? 0),
        discount_percentage: (response.data as any)?.discount_percentage ?? 0,
        quantity_available: response.data.quantity_available ?? 0,
        expiration_date: response.data.expiration_date ?? null,
        image_url: response.data.image_url ?? null,
        is_active: response.data.is_active,
        favorited_at: new Date().toISOString(),
        category: response.data.category ?? null,
        merchant: response.data.merchant ?? null
      })
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Impossible de récupérer les informations du produit'
      emitFavoritesError({ message })
      return null
    }
  }

  const toggleProductFavorite = async (payload: Omit<FavoriteItem, 'addedAt'>) => {
    await ensureInitialized()

    const alreadyFavorite = favoriteProductIds.value.has(payload.id)

    try {
      const response = await apiService.toggleFavoriteProduct(payload.id)
      if (!response.success) {
        throw new Error(response.message || 'Action favori impossible')
      }

      if (response.is_favorite) {
        if (alreadyFavorite) {
          emitFavoritesInfo({ message: 'Ce panier est déjà dans vos favoris' })
          return { success: true as const }
        }

        const favorite = await buildFavoriteFromPayload(payload)
        if (!favorite) {
          return { success: false as const, reason: 'hydrate_failed' as const }
        }

        productFavorites.value = [favorite, ...productFavorites.value]
        favoriteProductIds.value.add(favorite.id)
        emitFavoritesSuccess({ message: 'Panier ajouté à vos favoris' })
        return { success: true as const, data: favorite }
      }

      if (!alreadyFavorite) {
        // nothing to remove
        return { success: true as const, toggledOff: true as const }
      }

      productFavorites.value = productFavorites.value.filter(item => item.id !== payload.id)
      favoriteProductIds.value.delete(payload.id)
      emitFavoritesInfo({ message: 'Panier retiré de vos favoris' })
      return { success: true as const, toggledOff: true as const }
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Impossible de mettre à jour vos favoris'
      emitFavoritesError({
        message,
        operation: 'toggle-product',
        action: {
          label: 'Réessayer',
          callback: async () => {
            await toggleProductFavorite(payload)
          }
        }
      })
      return { success: false as const, reason: 'error' as const }
    }
  }

  const toggleFavorite = async (payload: Omit<FavoriteItem, 'addedAt'>) => {
    if (payload.type === 'merchant') {
      loadMerchantFavorites()
      const index = findMerchantIndex(payload.id)
      if (index === -1) {
        const { type: _type, ...rest } = payload
        return addMerchantFavorite(rest)
      }
      return removeMerchantFavorite(payload.id)
    }

    return toggleProductFavorite(payload)
  }

  const removeFavorite = async (id: number, type: FavoriteType) => {
    if (type === 'merchant') {
      loadMerchantFavorites()
      return removeMerchantFavorite(id)
    }

    if (!favoriteProductIds.value.has(id)) {
      return { success: false as const, reason: 'not_found' as const }
    }

    try {
      const response = await apiService.toggleFavoriteProduct(id)
      if (!response.success) {
        throw new Error(response.message || 'Action favori impossible')
      }

      productFavorites.value = productFavorites.value.filter(item => item.id !== id)
      favoriteProductIds.value.delete(id)
      emitFavoritesInfo({ message: 'Panier retiré de vos favoris' })
      return { success: true as const }
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Impossible de retirer ce favori'
      emitFavoritesError({ message })
      return { success: false as const, reason: 'error' as const }
    }
  }

  const isFavorite = (id: number, type: FavoriteType) => {
    if (type === 'product') {
      return favoriteProductIds.value.has(id)
    }

    if (!merchantsHydrated.value) {
      loadMerchantFavorites()
    }

    return merchantFavorites.value.some(item => item.id === id)
  }

  const clearFavorites = async () => {
    await ensureInitialized()

    const productIds = Array.from(favoriteProductIds.value)

    for (const id of productIds) {
      try {
        await apiService.toggleFavoriteProduct(id)
      } catch (error) {
        console.warn('Unable to clear product favorite', id, error)
      }
    }

    setProductFavorites([])
    merchantFavorites.value = []

    emitFavoritesInfo({ message: 'Tous vos favoris ont été effacés' })
  }

  return {
    items,
    loading,
    pendingOperation,
    favoritesCount,
    hasFavorites,
    groupedFavorites,
    initialize: ensureInitialized,
    toggleFavorite,
    removeFavorite,
    isFavorite,
    clearFavorites
  }
})

import { defineStore } from 'pinia'
import { computed, reactive, ref } from 'vue'
import type { Merchant } from '@/types'
import { merchantService, type MerchantDetail, type MerchantWithLocation } from '@/services/merchantService'
import { notify, type Notification } from '@/composables/useNotifications'

interface MerchantFetchOptions {
  withLocation?: boolean
  force?: boolean
  params?: Record<string, unknown>
  silent?: boolean
}

interface MerchantState {
  list: MerchantWithLocation[]
  loading: boolean
  lastFetchedAt: number | null
  lastFetchWithLocation: boolean
}

interface MerchantNotificationPayload {
  title?: string
  message: string
  action?: Notification['action']
  onClose?: Notification['onClose']
  operation?: string
}

const CACHE_DURATION = 5 * 60 * 1000 // 5 minutes

const normalizeMerchant = (merchant: Partial<MerchantWithLocation | MerchantDetail | Merchant>): MerchantWithLocation => {
  const baseMerchant = merchant as Partial<MerchantWithLocation>
  const user = baseMerchant.user ?? {
    city: (merchant as Merchant)?.city ?? null,
    address: (merchant as Merchant)?.address ?? null,
    phone: (merchant as Merchant)?.phone ?? null
  }

  return {
    id: (merchant as Merchant)?.id ?? 0,
    business_name: (merchant as Merchant)?.business_name ?? 'Commerçant',
    business_type: (merchant as Merchant)?.business_type ?? 'Commerce',
    city: (merchant as Merchant)?.city ?? user?.city ?? '',
    address: (merchant as Merchant)?.address ?? user?.address ?? undefined,
    phone: (merchant as Merchant)?.phone ?? user?.phone ?? '',
    is_verified: Boolean((merchant as Merchant)?.is_verified),
    latitude: baseMerchant.latitude ?? null,
    longitude: baseMerchant.longitude ?? null,
    distance_km: baseMerchant.distance_km ?? null,
    products_count: baseMerchant.products_count ?? undefined,
    user
  }
}

const extractMerchantList = (
  payload: MerchantWithLocation[] | { merchants?: MerchantWithLocation[] } | { data?: MerchantWithLocation[] }
): MerchantWithLocation[] => {
  if (Array.isArray(payload)) {
    return payload
  }

  if ('merchants' in payload && payload.merchants && Array.isArray(payload.merchants)) {
    return payload.merchants
  }

  if ('data' in payload && payload.data && Array.isArray(payload.data)) {
    return payload.data
  }

  return []
}

const extractMerchantDetail = (
  payload: MerchantDetail | { merchant?: MerchantDetail } | { data?: MerchantDetail }
): MerchantDetail | null => {
  if (!payload) {
    return null
  }

  const payloadAny = payload as { merchant?: MerchantDetail; data?: MerchantDetail }

  if ('merchant' in payload && payloadAny.merchant) {
    return payloadAny.merchant
  }

  if ('data' in payload && payloadAny.data) {
    return payloadAny.data
  }

  return payload as MerchantDetail
}

export const useMerchantsStore = defineStore('merchants', () => {
  const state = reactive<MerchantState>({
    list: [],
    loading: false,
    lastFetchedAt: null,
    lastFetchWithLocation: false
  })

  const detailsCache = ref<Map<number, MerchantDetail>>(new Map())
  const currentMerchantId = ref<number | null>(null)
  const detailLoading = ref(false)
  const pendingOperation = ref<string | null>(null)

  const merchants = computed(() => state.list)
  const hasMerchants = computed(() => state.list.length > 0)
  const isStale = (withLocation: boolean) => {
    if (!state.lastFetchedAt) {
      return true
    }

    if (withLocation && !state.lastFetchWithLocation) {
      return true
    }

    return Date.now() - state.lastFetchedAt > CACHE_DURATION
  }

  const emitMerchantNotification = (
    type: 'error' | 'info' | 'success',
    payload: MerchantNotificationPayload
  ) => {
    const { title = 'Commerçants', message, action, onClose, operation } = payload

    if (type === 'error' && operation) {
      pendingOperation.value = operation
    } else if (type !== 'error') {
      pendingOperation.value = null
    }

    const wrappedAction = action
      ? {
        label: action.label,
        callback: async () => {
          await action.callback()
          if (operation && pendingOperation.value === operation) {
            pendingOperation.value = null
          }
        }
      }
      : undefined

    const wrappedOnClose = () => {
      if (operation && pendingOperation.value === operation) {
        pendingOperation.value = null
      }
      onClose?.()
    }

    const options: Partial<Notification> = {
      action: wrappedAction,
      onClose: wrappedOnClose
    }

    if (type === 'error') {
      return notify.error(message, title, options)
    }

    if (type === 'info') {
      return notify.info(message, title, options)
    }

    return notify.success(message, title, options)
  }

  const emitMerchantError = (payload: MerchantNotificationPayload) =>
    emitMerchantNotification('error', payload)

  const fetchMerchants = async (options: MerchantFetchOptions = {}) => {
    const { withLocation = false, force = false, params, silent } = options

    if (!force && hasMerchants.value && !isStale(withLocation)) {
      return { success: true, fromCache: true, data: state.list }
    }

    state.loading = true

    try {
      const response = withLocation
        ? await merchantService.getMerchantsWithLocation(params)
        : await merchantService.getMerchants(params)

      if (!response.success) {
        throw new Error(response.message || 'Erreur lors du chargement des commerçants')
      }

      const merchantsData = extractMerchantList(response.data as any)
      state.list = merchantsData.map(normalizeMerchant)
      state.lastFetchedAt = Date.now()
      state.lastFetchWithLocation = withLocation

      if (pendingOperation.value === 'fetch-merchants') {
        pendingOperation.value = null
      }

      return { success: true, data: state.list }
    } catch (error: any) {
      const message = error?.message || 'Erreur lors du chargement des commerçants'
      emitMerchantError({
        message,
        operation: 'fetch-merchants',
        action: {
          label: 'Réessayer',
          callback: async () => {
            await fetchMerchants({ ...options, force: true })
          }
        },
        onClose: () => {
          if (!silent) {
            pendingOperation.value = null
          }
        }
      })
      return { success: false, error: message }
    } finally {
      state.loading = false
    }
  }

  const fetchMerchantDetail = async (id: number, options: { force?: boolean; silent?: boolean } = {}) => {
    const { force = false, silent } = options

    if (!force && detailsCache.value.has(id)) {
      const cached = detailsCache.value.get(id)!
      currentMerchantId.value = id
      return { success: true, data: cached, fromCache: true }
    }

    detailLoading.value = true

    try {
      const response = await merchantService.getMerchantDetail(id)

      if (!response.success) {
        throw new Error(response.message || 'Erreur lors du chargement du commerçant')
      }

      const payload = extractMerchantDetail(response.data as any)
      if (!payload) {
        throw new Error('Réponse invalide du serveur')
      }

      const merchant = {
        ...normalizeMerchant(payload),
        ...payload
      }

      detailsCache.value.set(id, merchant)
      currentMerchantId.value = id

      if (pendingOperation.value === 'fetch-merchant-detail') {
        pendingOperation.value = null
      }

      return { success: true, data: merchant }
    } catch (error: any) {
      const message = error?.message || 'Erreur lors du chargement du commerçant'
      emitMerchantError({
        message,
        operation: 'fetch-merchant-detail',
        action: {
          label: 'Réessayer',
          callback: async () => {
            await fetchMerchantDetail(id, { force: true, silent })
          }
        }
      })
      return { success: false, error: message }
    } finally {
      detailLoading.value = false
    }
  }

  const currentMerchant = computed(() => {
    if (currentMerchantId.value === null) {
      return null
    }

    return detailsCache.value.get(currentMerchantId.value) ?? null
  })

  const reset = () => {
    state.list = []
    state.lastFetchedAt = null
    state.lastFetchWithLocation = false
    detailsCache.value.clear()
    currentMerchantId.value = null
    pendingOperation.value = null
  }

  return {
    // State
    merchants,
    loading: computed(() => state.loading),
    detailLoading: computed(() => detailLoading.value),
    pendingOperation,
    currentMerchant,

    // Getters
    hasMerchants,

    // Actions
    fetchMerchants,
    fetchMerchantDetail,
    reset
  }
})

export type { MerchantWithLocation, MerchantDetail }

import { defineStore } from 'pinia'
import messagingService from '@/services/messagingService'
import { websocketService } from '@/services/websocketService'
import type { Conversation, ConversationMessage } from '@/types'

interface MessagingState {
  conversations: Conversation[]
  activeConversation: Conversation | null
  messages: ConversationMessage[]
  loading: boolean
  sending: boolean
  error: string | null
  wsConnected: boolean
  unsubscribe: (() => void) | null
}

export const useMessagingStore = defineStore('messaging', {
  state: (): MessagingState => ({
    conversations: [],
    activeConversation: null,
    messages: [],
    loading: false,
    sending: false,
    error: null,
    wsConnected: false,
    unsubscribe: null
  }),
  actions: {
    // WebSocket integration
    async connectWebSocket() {
      try {
        await websocketService.connect()
        this.wsConnected = true
        console.log('[Messaging] WebSocket connected')
      } catch (error) {
        console.warn('[Messaging] WebSocket connection failed, falling back to polling')
        this.wsConnected = false
      }
    },

    disconnectWebSocket() {
      if (this.unsubscribe) {
        this.unsubscribe()
        this.unsubscribe = null
      }
      this.wsConnected = false
    },

    subscribeToConversation(conversationId: number) {
      // Unsubscribe from previous conversation
      if (this.unsubscribe) {
        this.unsubscribe()
        this.unsubscribe = null
      }

      if (!this.wsConnected) {
        return
      }

      // Subscribe to new conversation
      this.unsubscribe = websocketService.subscribeToConversation(conversationId, (data) => {
        this.handleIncomingMessage(data)
      })
    },

    handleIncomingMessage(data: any) {
      if (!data) return

      // Handle new message
      if (data.type === 'new_message' && data.message) {
        const message = data.message as ConversationMessage

        // Add to messages if it's for active conversation
        if (this.activeConversation && message.conversation_id === this.activeConversation.id) {
          // Avoid duplicates
          const exists = this.messages.some(m => m.id === message.id)
          if (!exists) {
            this.messages.push(message)
          }
        }

        // Update conversation preview
        if (data.conversation) {
          this.upsertConversation(data.conversation)
        }
      }

      // Handle typing indicator
      if (data.type === 'typing') {
        // Could emit an event or update state for typing indicator
        console.log('[Messaging] User typing:', data.user_id)
      }

      // Handle read receipt
      if (data.type === 'read') {
        // Update message read status
        if (data.message_ids) {
          this.messages = this.messages.map(m => {
            if (data.message_ids.includes(m.id)) {
              return { ...m, read_at: data.read_at || new Date().toISOString() }
            }
            return m
          })
        }
      }
    },

    // Send typing indicator
    sendTypingIndicator() {
      if (!this.wsConnected || !this.activeConversation) return

      websocketService.send('typing', {
        conversation_id: this.activeConversation.id
      }, `conversation.${this.activeConversation.id}`)
    },

    setError(message: string | null) {
      this.error = message
    },

    upsertConversation(conversation: Conversation) {
      const index = this.conversations.findIndex(({ id }) => id === conversation.id)
      if (index >= 0) {
        this.conversations.splice(index, 1, conversation)
      } else {
        this.conversations.unshift(conversation)
      }
    },

    async fetchConversations(includeArchived = false) {
      this.loading = true
      this.error = null
      try {
        const response = await messagingService.listConversations(includeArchived)
        this.conversations = response.data.conversations
        return response
      } catch (error: any) {
        this.error = error?.message ?? 'Impossible de charger vos conversations.'
        throw error
      } finally {
        this.loading = false
      }
    },

    async loadConversation(
      conversationId: number,
      options: { perPage?: number; page?: number } = {}
    ) {
      this.loading = true
      this.error = null
      try {
        const response = await messagingService.getConversation(conversationId, options)
        this.activeConversation = response.data.conversation
        this.messages = response.data.messages
        this.upsertConversation(response.data.conversation)

        // Subscribe to WebSocket channel for real-time updates
        this.subscribeToConversation(conversationId)

        return response
      } catch (error: any) {
        this.error = error?.message ?? 'Impossible de charger la conversation sélectionnée.'
        throw error
      } finally {
        this.loading = false
      }
    },

    async ensureConversation(params: {
      conversationId?: number
      merchantId?: number
      consumerId?: number
    }) {
      this.loading = true
      this.error = null
      try {
        if (params.conversationId) {
          return await this.loadConversation(params.conversationId)
        }

        const creation = await messagingService.createConversation({
          merchantId: params.merchantId,
          consumerId: params.consumerId
        })

        const conversationId = creation.data.conversation.id
        this.upsertConversation(creation.data.conversation)

        const detail = await messagingService.getConversation(conversationId)
        this.activeConversation = detail.data.conversation
        this.messages = detail.data.messages
        this.upsertConversation(detail.data.conversation)
        return detail
      } catch (error: any) {
        this.error = error?.message ?? 'Impossible d\'ouvrir la messagerie.'
        throw error
      } finally {
        this.loading = false
      }
    },

    async sendMessage(content: string) {
      if (!this.activeConversation) {
        throw new Error('Aucune conversation active')
      }

      this.sending = true
      this.error = null
      try {
        const response = await messagingService.sendMessage(this.activeConversation.id, content)
        this.activeConversation = response.data.conversation
        this.messages = [...this.messages, response.data.message]
        this.upsertConversation(response.data.conversation)
        return response
      } catch (error: any) {
        this.error = error?.message ?? "Impossible d'envoyer le message."
        throw error
      } finally {
        this.sending = false
      }
    },

    async refreshConversationsList() {
      try {
        await this.fetchConversations()
      } catch (error) {
        // erreur déjà gérée dans fetchConversations
      }
    },

    clearActiveConversation() {
      this.activeConversation = null
      this.messages = []
    }
  }
})

import { defineStore } from 'pinia'
import { computed, reactive, ref } from 'vue'
import { useAuthStore } from '@/stores/auth'
import {
  fetchNotifications,
  markNotificationAsRead,
  markAllNotificationsAsRead,
  subscribeToPush,
  updateNotificationPreferences,
  type ServerNotification
} from '@/services/notificationService'

// ToastNotification interface removed - using useNotifications composable

interface PaginationState {
  currentPage: number
  lastPage: number
  perPage: number
  total: number
}

interface ChannelPreferences {
  email: boolean
  sms: boolean
  push: boolean
}

export const useNotificationStore = defineStore('notification', () => {
  // toasts removed - using useNotifications composable
  const serverNotifications = ref<ServerNotification[]>([])
  const pagination = reactive<PaginationState>({
    currentPage: 1,
    lastPage: 1,
    perPage: 20,
    total: 0
  })
  const loading = ref(false)
  const preferences = reactive<ChannelPreferences>({
    email: true,
    sms: false,
    push: false
  })

  const unreadCount = computed(() => serverNotifications.value.filter(n => !n.is_read).length)

  const authStore = useAuthStore()

  // setToast removed - using useNotifications composable

  // removeToast removed - using useNotifications composable

  // clearToasts removed - using useNotifications composable

  const hydratePreferencesFromUser = () => {
    if (!authStore.user) return

    preferences.email = !!authStore.user.prefers_email_notifications
    preferences.sms = !!authStore.user.prefers_sms_notifications
    preferences.push = !!authStore.user.prefers_push_notifications
  }

  const loadNotifications = async (options: { unread?: boolean; page?: number } = {}) => {
    loading.value = true
    try {
      const response = await fetchNotifications({
        unread: options.unread,
        page: options.page,
        perPage: pagination.perPage
      })

      serverNotifications.value = response.data
      pagination.currentPage = response.meta.current_page
      pagination.lastPage = response.meta.last_page
      pagination.perPage = response.meta.per_page
      pagination.total = response.meta.total
    } finally {
      loading.value = false
    }
  }

  const markAsRead = async (id: number) => {
    const notification = serverNotifications.value.find(item => item.id === id)
    if (!notification || notification.is_read) return

    await markNotificationAsRead(id)
    notification.is_read = true
  }

  const markAllAsRead = async () => {
    if (!unreadCount.value) return
    await markAllNotificationsAsRead()
    serverNotifications.value = serverNotifications.value.map(notification => ({
      ...notification,
      is_read: true
    }))
  }

  const savePreferences = async (updated: ChannelPreferences) => {
    const response = await updateNotificationPreferences({
      email: updated.email,
      sms: updated.sms,
      push: updated.push
    })

    preferences.email = response.data.prefers_email_notifications
    preferences.sms = response.data.prefers_sms_notifications
    preferences.push = response.data.prefers_push_notifications

    if (authStore.user) {
      authStore.user.prefers_email_notifications = preferences.email
      authStore.user.prefers_sms_notifications = preferences.sms
      authStore.user.prefers_push_notifications = preferences.push
      localStorage.setItem('user', JSON.stringify(authStore.user))
    }

    return { ...preferences }
  }

  const ensurePushSubscription = async () => {
    if (!preferences.push) {
      return null
    }

    try {
      return await subscribeToPush()
    } catch (error) {
      console.warn('Failed to subscribe to push notifications', error)
      return null
    }
  }

  return {
    // state
    serverNotifications,
    pagination,
    loading,
    preferences,
    unreadCount,

    // server helpers
    hydratePreferencesFromUser,
    loadNotifications,
    markAsRead,
    markAllAsRead,
    savePreferences,
    ensurePushSubscription
  }
})

import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import { notify } from '@/composables/useNotifications'

const STORAGE_KEY = 'antigaspi_onboarding_completed'

export const useOnboardingStore = defineStore('onboarding', () => {
  const initialized = ref(false)
  const loading = ref(false)
  const completed = ref(false)
  const currentStep = ref(0)
  const totalSteps = ref(3)

  const init = () => {
    if (initialized.value) {
      return
    }

    if (typeof window !== 'undefined') {
      completed.value = window.localStorage.getItem(STORAGE_KEY) === 'true'
    }

    initialized.value = true
  }

  const shouldShowOnboarding = computed(() => !completed.value)

  const persistCompletion = () => {
    if (typeof window === 'undefined') {
      return
    }

    try {
      window.localStorage.setItem(STORAGE_KEY, completed.value ? 'true' : 'false')
    } catch (error) {
      console.error('Unable to persist onboarding status', error)
    }
  }

  const goToStep = (stepIndex: number) => {
    const normalizedIndex = Math.max(0, Math.min(stepIndex, totalSteps.value - 1))
    currentStep.value = normalizedIndex
    return normalizedIndex
  }

  const nextStep = async () => {
    if (currentStep.value < totalSteps.value - 1) {
      currentStep.value += 1
      return { done: false, step: currentStep.value }
    }

    return completeOnboarding()
  }

  const previousStep = () => {
    if (currentStep.value === 0) {
      return currentStep.value
    }

    currentStep.value -= 1
    return currentStep.value
  }

  const completeOnboarding = () => {
    completed.value = true
    persistCompletion()
    notify.success('Bienvenue sur AntiGaspi !', 'Onboarding terminé')
    return { done: true as const }
  }

  const reset = () => {
    completed.value = false
    currentStep.value = 0
    persistCompletion()
  }

  const skipOnboarding = () => {
    completed.value = true
    persistCompletion()
    notify.info('Vous pourrez retrouver ce guide plus tard dans votre profil.', 'Onboarding ignoré')
    return { skipped: true as const }
  }

  return {
    loading,
    currentStep,
    totalSteps,
    shouldShowOnboarding,
    init,
    goToStep,
    nextStep,
    previousStep,
    completeOnboarding,
    reset,
    skipOnboarding
  }
})

import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import { apiService } from '@/services/api'
import type { Payment, PaymentStatus, PaymentMethod } from '@/types'

const FINAL_STATUSES: PaymentStatus[] = ['success', 'failed', 'on_site', 'refunded']

const isFinalStatus = (status?: PaymentStatus | null) => {
  if (!status) return false
  return FINAL_STATUSES.includes(status)
}

export const usePaymentsStore = defineStore('payments', () => {
  const currentPayment = ref<Payment | null>(null)
  const paymentsByReservation = ref<Record<number, Payment>>({})
  const loading = ref(false)
  const error = ref<string | null>(null)
  const pollingInterval = ref<ReturnType<typeof setInterval> | null>(null)
  const pollingPaymentId = ref<number | null>(null)

  const clearError = () => {
    error.value = null
  }

  const setError = (message: string) => {
    error.value = message
  }

  const recordPayment = (payment: Payment | null) => {
    currentPayment.value = payment

    if (payment) {
      paymentsByReservation.value[payment.reservation_id] = payment

      if (isFinalStatus(payment.status)) {
        stopPolling()
      }
    }
  }

  const stopPolling = () => {
    if (pollingInterval.value) {
      clearInterval(pollingInterval.value)
      pollingInterval.value = null
    }
    pollingPaymentId.value = null
  }

  const refreshPayment = async (paymentId: number) => {
    try {
      loading.value = true
      clearError()

      const response = await apiService.getPayment(paymentId)
      if (!response?.data) {
        throw new Error('Réponse de paiement invalide')
      }

      recordPayment(response.data)

      return { success: true as const, data: response.data }
    } catch (err: any) {
      const message = err?.message || 'Impossible de récupérer le statut du paiement'
      setError(message)
      return { success: false as const, error: message }
    } finally {
      loading.value = false
    }
  }

  const startPolling = (paymentId: number, intervalMs = 5000) => {
    if (pollingPaymentId.value === paymentId && pollingInterval.value) {
      return
    }

    stopPolling()
    pollingPaymentId.value = paymentId

    pollingInterval.value = setInterval(async () => {
      const result = await refreshPayment(paymentId)
      if (result.success && isFinalStatus(result.data.status)) {
        stopPolling()
      }
    }, intervalMs)
  }

  const cancelPayment = async (paymentId: number, reason?: string) => {
    try {
      loading.value = true
      clearError()

      const response = await apiService.cancelPayment(paymentId, reason)
      recordPayment(response.data)

      return { success: true as const, data: response.data }
    } catch (err: any) {
      const message = err?.message || 'Impossible d\'annuler le paiement'
      setError(message)
      return { success: false as const, error: message }
    } finally {
      loading.value = false
    }
  }

  const initiatePayment = async (params: {
    reservationId: number
    paymentMethod: PaymentMethod
    customerPhone?: string
    customerEmail?: string
    notes?: string
    currency?: string
  }) => {
    try {
      loading.value = true
      clearError()

      const response = await apiService.initiatePayment(params)
      recordPayment(response.data)

      return { success: true as const, data: response.data }
    } catch (err: any) {
      const message = err?.message || 'Impossible d\'initialiser le paiement'
      setError(message)
      return { success: false as const, error: message }
    } finally {
      loading.value = false
    }
  }

  const getPaymentForReservation = (reservationId: number) => {
    return paymentsByReservation.value[reservationId] ?? null
  }

  const clearPayment = () => {
    currentPayment.value = null
  }

  const isProcessing = computed(() => loading.value)
  const hasError = computed(() => Boolean(error.value))

  return {
    currentPayment,
    paymentsByReservation,
    loading,
    error,
    pollingPaymentId,
    isProcessing,
    hasError,
    recordPayment,
    clearPayment,
    getPaymentForReservation,
    refreshPayment,
    startPolling,
    stopPolling,
    cancelPayment,
    initiatePayment
  }
})

export { isFinalStatus }

import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import type { Product, ProductFilters } from '@/types'
import { apiService } from '@/services/api'
import { notify } from '@/composables/useNotifications'

export const useProductsStore = defineStore('products', () => {
  const products = ref<Product[]>([])
  const currentProduct = ref<Product | null>(null)
  const loading = ref(false)
  // error ref removed - using useNotifications composable
  const filters = ref<ProductFilters>({
    search: '',
    category: '',
    merchant: '',
    max_price: undefined,
    max_expiry_days: undefined,
    page: 1,
    per_page: 12
  })
  const pagination = ref({
    current_page: 1,
    last_page: 1,
    per_page: 12,
    total: 0
  })

  const filteredProducts = computed(() => {
    return products.value.filter(product => {
      const matchesSearch = !filters.value.search ||
        product.name.toLowerCase().includes(filters.value.search.toLowerCase()) ||
        product.description.toLowerCase().includes(filters.value.search.toLowerCase())

      const matchesCategory = !filters.value.category ||
        product.category.name.toLowerCase() === filters.value.category.toLowerCase()

      const matchesMerchant = !filters.value.merchant ||
        product.merchant.business_name.toLowerCase().includes(filters.value.merchant.toLowerCase())

      const matchesPrice = !filters.value.max_price ||
        parseFloat(product.discounted_price) <= filters.value.max_price

      const matchesExpiry = filters.value.max_expiry_days === undefined ||
        product.days_until_expiration <= filters.value.max_expiry_days

      return matchesSearch && matchesCategory && matchesMerchant && matchesPrice && matchesExpiry
    })
  })

  const categories = computed(() => {
    const uniqueCategories = new Map()
    products.value.forEach(product => {
      if (!uniqueCategories.has(product.category.id)) {
        uniqueCategories.set(product.category.id, product.category)
      }
    })
    return Array.from(uniqueCategories.values())
  })

  const merchants = computed(() => {
    const uniqueMerchants = new Map()
    products.value.forEach(product => {
      if (!uniqueMerchants.has(product.merchant.id)) {
        uniqueMerchants.set(product.merchant.id, product.merchant)
      }
    })
    return Array.from(uniqueMerchants.values())
  })

  const selectedProduct = computed<Product | null>({
    get: () => currentProduct.value,
    set: value => {
      currentProduct.value = value
    }
  })

  // setError removed - using useNotifications composable

  // clearError removed - using useNotifications composable

  const setFilters = (newFilters: Partial<ProductFilters>) => {
    filters.value = { ...filters.value, ...newFilters }
  }

  const clearFilters = () => {
    filters.value = {
      search: '',
      category: '',
      merchant: '',
      max_price: undefined,
      max_expiry_days: undefined,
      page: 1,
      per_page: 12
    }
  }

  const fetchProducts = async (customFilters?: ProductFilters) => {
    try {
      loading.value = true

      const filtersToUse = customFilters || filters.value
      const response = await apiService.getProducts(filtersToUse)

      products.value = response.data
      if (response.pagination) {
        pagination.value = response.pagination
      }

      return { success: true }
    } catch (err: any) {
      notify.error(err.message || 'Erreur lors du chargement des produits', 'Catalogue', {
        action: {
          label: 'Réessayer',
          callback: () => { fetchProducts(customFilters) }
        }
      })
      return { success: false, error: err.message }
    } finally {
      loading.value = false
    }
  }

  const fetchProduct = async (id: number) => {
    try {
      loading.value = true

      const resolver = typeof (apiService as any).getProductById === 'function'
        ? (apiService as any).getProductById.bind(apiService)
        : apiService.getProduct.bind(apiService)

      const response = await resolver(id)
      currentProduct.value = response.data

      return { success: true }
    } catch (err: any) {
      notify.error(err.message || 'Erreur lors du chargement du produit', 'Produit', {
        action: {
          label: 'Réessayer',
          callback: () => { fetchProduct(id) }
        }
      })
      return { success: false, error: err.message }
    } finally {
      loading.value = false
    }
  }

  const createProduct = async (productData: Partial<Product>) => {
    try {
      loading.value = true

      const response = await apiService.createProduct(productData)

      // Add new product to the list
      products.value.unshift(response.data)
      notify.success('Produit créé avec succès', 'Catalogue', { duration: 3000 })

      return { success: true, data: response.data }
    } catch (err: any) {
      notify.error(err.message || 'Erreur lors de la création du produit', 'Catalogue', {
        action: {
          label: 'Réessayer',
          callback: () => { createProduct(productData) }
        }
      })
      return { success: false, error: err.message }
    } finally {
      loading.value = false
    }
  }

  const updateProduct = async (id: number, productData: Partial<Product>) => {
    try {
      loading.value = true

      const response = await apiService.updateProduct(id, productData)

      // Update product in the list
      const index = products.value.findIndex(p => p.id === id)
      if (index !== -1) {
        products.value[index] = response.data
      }

      if (currentProduct.value?.id === id) {
        currentProduct.value = response.data
      }

      notify.success('Produit mis à jour avec succès', 'Catalogue', { duration: 3000 })
      return { success: true, data: response.data }
    } catch (err: any) {
      notify.error(err.message || 'Erreur lors de la mise à jour du produit', 'Catalogue', {
        action: {
          label: 'Réessayer',
          callback: () => { updateProduct(id, productData) }
        }
      })
      return { success: false, error: err.message }
    } finally {
      loading.value = false
    }
  }

  const deleteProduct = async (id: number) => {
    try {
      loading.value = true

      await apiService.deleteProduct(id)

      // Remove product from the list
      products.value = products.value.filter(p => p.id !== id)

      if (currentProduct.value?.id === id) {
        currentProduct.value = null
      }

      notify.success('Produit supprimé avec succès', 'Catalogue', { duration: 3000 })
      return { success: true }
    } catch (err: any) {
      notify.error(err.message || 'Erreur lors de la suppression du produit', 'Catalogue', {
        action: {
          label: 'Réessayer',
          callback: () => { deleteProduct(id) }
        }
      })
      return { success: false, error: err.message }
    } finally {
      loading.value = false
    }
  }

  const getProductsByCategory = (categoryId: number) => {
    return products.value.filter(product => {
      const productCategoryId = product.category?.id ?? (product as any).categoryId
      return productCategoryId === categoryId
    })
  }

  const getProductsByPriceRange = (min: number, max: number) => {
    return products.value.filter(product => {
      const price = typeof (product as any).price === 'number'
        ? (product as any).price
        : parseFloat((product as any).discounted_price ?? (product as any).original_price)

      return price >= min && price <= max
    })
  }

  const searchProducts = (query: string) => {
    const normalizedQuery = query.toLowerCase()
    return products.value.filter(product => {
      return product.name.toLowerCase().includes(normalizedQuery) ||
        product.description.toLowerCase().includes(normalizedQuery)
    })
  }

  const fetchProductById = (id: number) => fetchProduct(id)
  const addProduct = (payload: Partial<Product>) => createProduct(payload)

  return {
    // State
    products,
    currentProduct,
    selectedProduct,
    loading,
    filters,
    pagination,

    // Getters
    filteredProducts,
    categories,
    merchants,

    // Actions
    fetchProducts,
    fetchProduct,
    fetchProductById,
    createProduct,
    addProduct,
    updateProduct,
    deleteProduct,
    setFilters,
    clearFilters,
    getProductsByCategory,
    getProductsByPriceRange,
    searchProducts
  }
})

import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import type { Reservation, ReservationCreationPayload, Payment } from '@/types'
import { apiService } from '@/services/api'
import { notify } from '@/composables/useNotifications'

export const useReservationsStore = defineStore('reservations', () => {
  const reservations = ref<Reservation[]>([])
  const merchantReservations = ref<Reservation[]>([])
  const loading = ref(false)
  const selectedReservation = ref<Reservation | null>(null)

  const normalizeReservation = (reservation: Reservation): Reservation => {
    const normalizedQuantity = reservation.quantity ?? reservation.quantity_reserved ?? 0
    const normalizedQuantityReserved = reservation.quantity_reserved ?? normalizedQuantity

    return {
      ...reservation,
      quantity: normalizedQuantity,
      quantity_reserved: normalizedQuantityReserved,
      latest_payment: reservation.latest_payment ?? null
    }
  }

  const pendingReservations = computed(() =>
    reservations.value.filter(r => r.status === 'pending')
  )

  const confirmedReservations = computed(() =>
    reservations.value.filter(r => r.status === 'confirmed')
  )

  const completedReservations = computed(() =>
    reservations.value.filter(r => r.status === 'completed')
  )

  const cancelledReservations = computed(() =>
    reservations.value.filter(r => r.status === 'cancelled')
  )

  const activeReservations = computed(() =>
    reservations.value.filter(r => ['pending', 'confirmed'].includes(r.status))
  )

  const totalSavings = computed(() =>
    completedReservations.value.reduce((total, reservation) => {
      const savings = (reservation.original_price - reservation.discounted_price) * reservation.quantity
      return total + savings
    }, 0)
  )

  const totalReservationValue = computed(() => {
    return reservations.value.reduce((total, reservation) => {
      const explicitTotal = (reservation as any).totalPrice
      if (typeof explicitTotal === 'number') {
        return total + explicitTotal
      }

      const unitPrice = (reservation as any).discounted_price ?? (reservation as any).price ?? 0
      const quantity = reservation.quantity ?? 0
      return total + unitPrice * quantity
    }, 0)
  })

  const pendingMerchantReservations = computed(() =>
    merchantReservations.value.filter(r => r.status === 'pending')
  )

  const confirmedMerchantReservations = computed(() =>
    merchantReservations.value.filter(r => r.status === 'confirmed')
  )

  const createRetryableNotification = (
    message: string,
    retryOperation: () => Promise<unknown>
  ) => {
    let hasClosed = false

    notify.error(message, 'Réservations', {
      action: {
        label: 'Réessayer',
        callback: async () => {
          if (loading.value) return

          try {
            await retryOperation()
          } catch (retryError) {
            console.error('Reservation retry failed:', retryError)
          }
        }
      },
      onClose: () => {
        if (hasClosed) return
        hasClosed = true
      }
    })
  }

  const fetchReservations = async () => {
    try {
      loading.value = true

      const response = await apiService.getReservations()
      reservations.value = response.data.map(normalizeReservation)
      if (reservations.value.length > 0) {
        selectedReservation.value = reservations.value[0]
      }

      return { success: true }
    } catch (err: any) {
      createRetryableNotification(
        err.message || 'Erreur lors du chargement des réservations',
        () => fetchReservations()
      )
      return { success: false, error: err.message }
    } finally {
      loading.value = false
    }
  }

  const createReservation = async (payload: ReservationCreationPayload) => {
    try {
      loading.value = true

      const response = await apiService.createReservation(payload)

      // Add new reservation to the list
      const normalizedReservation = normalizeReservation(response.data)
      reservations.value.unshift(normalizedReservation)

      const payment: Payment | null = response.payment ?? null

      selectedReservation.value = normalizedReservation

      notify.success('Réservation créée avec succès', 'Réservations', { duration: 3000 })

      return { success: true, data: normalizedReservation, payment }
    } catch (err: any) {
      createRetryableNotification(
        err.message || 'Erreur lors de la réservation',
        () => createReservation(payload)
      )
      return { success: false, error: err.message }
    } finally {
      loading.value = false
    }
  }

  const cancelReservation = async (id: number) => {
    try {
      loading.value = true

      await apiService.cancelReservation(id)

      // Update reservation status in the list
      const reservation = reservations.value.find(r => r.id === id)
      if (reservation) {
        reservation.status = 'cancelled'
        reservation.cancelled_at = new Date().toISOString()
      }

      notify.success('Réservation annulée', 'Réservations', { duration: 3000 })

      return { success: true }
    } catch (err: any) {
      createRetryableNotification(
        err.message || 'Erreur lors de l\'annulation',
        () => cancelReservation(id)
      )
      return { success: false, error: err.message }
    } finally {
      loading.value = false
    }
  }

  const fetchMerchantReservations = async () => {
    try {
      loading.value = true

      const response = await apiService.getMerchantReservations()
      merchantReservations.value = response.data.map(normalizeReservation)

      return { success: true }
    } catch (err: any) {
      createRetryableNotification(
        err.message || 'Erreur lors du chargement des réservations',
        () => fetchMerchantReservations()
      )
      return { success: false, error: err.message }
    } finally {
      loading.value = false
    }
  }

  const confirmReservation = async (id: number) => {
    try {
      loading.value = true

      const response = await apiService.confirmReservation(id)
      const normalizedReservation = normalizeReservation(response.data)

      // Update reservation in the list
      const index = merchantReservations.value.findIndex(r => r.id === id)
      if (index !== -1) {
        merchantReservations.value[index] = normalizedReservation
      }

      notify.success('Réservation confirmée', 'Réservations', { duration: 3000 })

      return { success: true, data: normalizedReservation }
    } catch (err: any) {
      createRetryableNotification(
        err.message || 'Erreur lors de la confirmation',
        () => confirmReservation(id)
      )
      return { success: false, error: err.message }
    } finally {
      loading.value = false
    }
  }

  const getReservationById = (id: number): Reservation | undefined => {
    return reservations.value.find(r => r.id === id) ||
           merchantReservations.value.find(r => r.id === id)
  }

  const clearReservations = () => {
    reservations.value = []
    merchantReservations.value = []
    selectedReservation.value = null
  }

  const updateStatus = async (id: number, status: Reservation['status']) => {
    try {
      loading.value = true

      const api = apiService as any
      let response: { data?: Reservation } | undefined

      if (typeof api.updateReservationStatus === 'function') {
        response = await api.updateReservationStatus(id, status)
      } else if (status === 'cancelled') {
        await cancelReservation(id)
        return { success: true }
      } else if (status === 'confirmed') {
        response = await apiService.confirmReservation(id)
      } else {
        const current = getReservationById(id)
        if (current) {
          response = { data: { ...current, status } as Reservation }
        }
      }

      if (response?.data) {
        const normalized = normalizeReservation(response.data)
        const index = reservations.value.findIndex(r => r.id === id)
        if (index !== -1) {
          reservations.value[index] = normalized
        }

        const merchantIndex = merchantReservations.value.findIndex(r => r.id === id)
        if (merchantIndex !== -1) {
          merchantReservations.value[merchantIndex] = normalized
        }

        selectedReservation.value = normalized
      }

      return { success: true, data: response?.data ?? null }
    } catch (err: any) {
      createRetryableNotification(
        err.message || 'Erreur lors de la mise à jour de la réservation',
        () => updateStatus(id, status)
      )
      return { success: false, error: err.message }
    } finally {
      loading.value = false
    }
  }

  const validateReservationData = (payload: Partial<ReservationCreationPayload>) => {
    if (!payload) return false
    const hasProduct = typeof payload.productId === 'number' && payload.productId > 0
    const hasQuantity = typeof payload.quantity === 'number' && payload.quantity > 0

    if (!hasProduct || !hasQuantity) {
      return false
    }

    if (payload.pickupDate) {
      const pickupTime = Date.parse(payload.pickupDate)
      if (Number.isNaN(pickupTime)) {
        return false
      }
    }

    return true
  }

  return {
    // State
    reservations,
    merchantReservations,
    loading,
    selectedReservation,

    // Getters
    pendingReservations,
    confirmedReservations,
    completedReservations,
    cancelledReservations,
    activeReservations,
    totalSavings,
    totalReservationValue,
    pendingMerchantReservations,
    confirmedMerchantReservations,

    // Actions
    fetchReservations,
    createReservation,
    cancelReservation,
    fetchMerchantReservations,
    confirmReservation,
    getReservationById,
    clearReservations,
    updateStatus,
    validateReservationData
  }
})

import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import type { Review } from '@/types'
import { apiService } from '@/services/api'
import { notify } from '@/composables/useNotifications'

interface ReviewsState {
  reviews: Review[]
  loading: boolean
  pagination: {
    current_page: number
    last_page: number
    per_page: number
    total: number
  }
}

export const useReviewsStore = defineStore('reviews', () => {
  const state = ref<ReviewsState>({
    reviews: [],
    loading: false,
    pagination: {
      current_page: 1,
      last_page: 1,
      per_page: 15,
      total: 0
    }
  })

  // Getters
  const reviews = computed(() => state.value.reviews)
  const loading = computed(() => state.value.loading)
  const pagination = computed(() => state.value.pagination)

  // Actions
  const fetchReviews = async (params: { merchantId?: number; productId?: number; page?: number }) => {
    try {
      state.value.loading = true
      const response = await apiService.getReviewsList({
        merchant_id: params.merchantId!,
        product_id: params.productId,
        page: params.page,
        per_page: 15
      })

      if (params.page === 1 || !params.page) {
        state.value.reviews = response.data
      } else {
        state.value.reviews.push(...response.data)
      }

      if (response.pagination) {
        state.value.pagination = response.pagination
      }
      return { success: true }
    } catch (err: any) {
      notify.error(err.message || 'Erreur lors du chargement des avis', 'Avis')
      return { success: false, error: err.message }
    } finally {
      state.value.loading = false
    }
  }

  const createReview = async (data: {
    merchantId: number
    productId?: number
    rating: number
    title?: string
    comment?: string
  }) => {
    try {
      state.value.loading = true
      const response = await apiService.createReview({
        merchant_id: data.merchantId,
        product_id: data.productId,
        rating: data.rating,
        title: data.title,
        comment: data.comment
      })

      notify.success('Avis publié avec succès!', 'Avis', { duration: 3000 })

      // Refresh reviews list
      await fetchReviews({ merchantId: data.merchantId })

      return { success: true, data: response.data }
    } catch (err: any) {
      notify.error(err.message || 'Erreur lors de la création de l\'avis', 'Avis')
      return { success: false, error: err.message }
    } finally {
      state.value.loading = false
    }
  }

  const clearReviews = () => {
    state.value.reviews = []
    state.value.pagination = {
      current_page: 1,
      last_page: 1,
      per_page: 15,
      total: 0
    }
  }

  return {
    // State
    state,
    reviews,
    loading,
    pagination,

    // Actions
    fetchReviews,
    createReview,
    clearReviews
  }
})

import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import { walletService } from '@/services/walletService'
import type {
  Wallet,
  WalletTransaction,
  WalletStats,
  TransactionFilters
} from '@/types/wallet'

// Error type for typed error handling
interface StoreError {
  message?: string
}

export const useWalletStore = defineStore('wallet', () => {
  // State
  const wallet = ref<Wallet | null>(null)
  const transactions = ref<WalletTransaction[]>([])
  const transactionsPagination = ref<any>(null)
  const stats = ref<WalletStats | null>(null)
  const loading = ref(false)
  const transactionsLoading = ref(false)
  const error = ref<string | null>(null)

  // Getters
  const hasWallet = computed(() => wallet.value !== null)
  const isActive = computed(() => wallet.value?.is_active ?? false)
  const hasPin = computed(() => wallet.value?.has_pin ?? false)
  const balance = computed(() => wallet.value?.balance ?? 0)
  const formattedBalance = computed(() => wallet.value?.formatted_balance ?? '0 XOF')
  const dailyLimit = computed(() => wallet.value?.daily_limit ?? 0)
  const remainingDailyLimit = computed(() => wallet.value?.remaining_daily_limit ?? 0)
  const currency = computed(() => wallet.value?.currency ?? 'XOF')

  const canPay = computed(() => (amount: number) => {
    if (!wallet.value || !wallet.value.is_active) return false
    if (balance.value < amount) return false
    if ((dailyLimit.value - remainingDailyLimit.value + amount) > dailyLimit.value) return false
    return hasPin.value
  })

  const dailySpent = computed(() => {
    return dailyLimit.value - remainingDailyLimit.value
  })

  const dailyLimitUsagePercentage = computed(() => {
    if (dailyLimit.value === 0) return 0
    return (dailySpent.value / dailyLimit.value) * 100
  })

  // Actions
  const fetchWallet = async (): Promise<void> => {
    loading.value = true
    error.value = null

    try {
      const response = await walletService.getWallet()
      if (response.success && response.data) {
        wallet.value = response.data.wallet
      } else {
        throw new Error(response.message || 'Erreur lors de la récupération du portefeuille')
      }
    } catch (err: unknown) {
      const e = err as StoreError
      error.value = e.message || 'Erreur lors de la récupération du portefeuille'
      console.error('Fetch wallet error:', err)
    } finally {
      loading.value = false
    }
  }

