} as const

export type ErrorCode = typeof ERROR_CODES[keyof typeof ERROR_CODES]

export const ERROR_MESSAGES: Record<ErrorCode, string> = {
  [ERROR_CODES.NETWORK_OFFLINE]: 'Vous semblez être hors ligne. Vérifiez votre connexion internet.',
  [ERROR_CODES.NETWORK_TIMEOUT]: 'La connexion a pris trop de temps. Réessayez dans quelques instants.',
  [ERROR_CODES.NETWORK_CONNECTION_FAILED]: 'Impossible de se connecter au serveur. Vérifiez votre connexion.',
  [ERROR_CODES.API_UNAUTHORIZED]: 'Votre session a expiré. Veuillez vous reconnecter.',
  [ERROR_CODES.API_FORBIDDEN]: 'Vous n avez pas les permissions nécessaires pour cette action.',
  [ERROR_CODES.API_NOT_FOUND]: 'La ressource demandée est introuvable.',
  [ERROR_CODES.API_VALIDATION_FAILED]: 'Les informations saisies ne sont pas valides.',
  [ERROR_CODES.API_SERVER_ERROR]: 'Erreur temporaire du serveur. Réessayez dans quelques instants.',
  [ERROR_CODES.API_RATE_LIMITED]: 'Trop de requêtes. Attendez un moment avant de réessayer.',
  [ERROR_CODES.COMPONENT_MOUNT_FAILED]: 'Erreur lors du chargement du composant.',
  [ERROR_CODES.COMPONENT_RENDER_ERROR]: 'Erreur d affichage du composant.',
  [ERROR_CODES.COMPONENT_PROP_VALIDATION]: 'Paramètres de composant invalides.',
  [ERROR_CODES.APP_INITIALIZATION_FAILED]: 'Échec du démarrage de l application.',
  [ERROR_CODES.APP_NAVIGATION_ERROR]: 'Erreur de navigation.',
  [ERROR_CODES.APP_STATE_CORRUPTION]: 'État de l application corrompu.',
  [ERROR_CODES.USER_INPUT_INVALID]: 'Veuillez vérifier les informations saisies.',
  [ERROR_CODES.USER_PERMISSION_DENIED]: 'Permission refusée pour cette action.',
  [ERROR_CODES.USER_SESSION_EXPIRED]: 'Votre session a expiré. Reconnectez-vous.'
}

export function classifyError(error: unknown): { code: ErrorCode; severity: ErrorSeverity } {
  if (!error) {
    return { code: ERROR_CODES.APP_STATE_CORRUPTION, severity: 'critical' }
  }

  const message = getErrorMessage(error).toLowerCase()

  if (!navigator.onLine) {
    return { code: ERROR_CODES.NETWORK_OFFLINE, severity: 'warning' }
  }

  if (message.includes('timeout') || message.includes('aborted')) {
    return { code: ERROR_CODES.NETWORK_TIMEOUT, severity: 'warning' }
  }

  if (message.includes('network') || message.includes('fetch')) {
    return { code: ERROR_CODES.NETWORK_CONNECTION_FAILED, severity: 'error' }
  }

  if (message.includes('401') || message.includes('unauthorized')) {
    return { code: ERROR_CODES.API_UNAUTHORIZED, severity: 'critical' }
  }

  if (message.includes('403') || message.includes('forbidden')) {
    return { code: ERROR_CODES.API_FORBIDDEN, severity: 'critical' }
  }

  if (message.includes('404') || message.includes('not found')) {
    return { code: ERROR_CODES.API_NOT_FOUND, severity: 'warning' }
  }

  if (message.includes('400') || message.includes('validation')) {
    return { code: ERROR_CODES.API_VALIDATION_FAILED, severity: 'warning' }
  }

  if (message.includes('500') || message.includes('server error')) {
    return { code: ERROR_CODES.API_SERVER_ERROR, severity: 'error' }
  }

  if (message.includes('429') || message.includes('rate limit')) {
    return { code: ERROR_CODES.API_RATE_LIMITED, severity: 'warning' }
  }

  if (message.includes('component') || message.includes('render')) {
    return { code: ERROR_CODES.COMPONENT_RENDER_ERROR, severity: 'error' }
  }

  return { code: ERROR_CODES.APP_STATE_CORRUPTION, severity: 'error' }
}

function getErrorMessage(error: unknown): string {
  if (error instanceof Error) return error.message
  if (typeof error === 'string') return error
  if (error && typeof error === 'object' && 'message' in error) {
    return String((error as any).message)
  }
  return 'Unknown error'
}

export function getUserFriendlyMessage(errorCode: ErrorCode): string {
  return ERROR_MESSAGES[errorCode] || 'Une erreur inattendue est survenue.'
}

export function isRetryableError(errorCode: ErrorCode): boolean {
  const retryableCodes: ErrorCode[] = [
    ERROR_CODES.NETWORK_TIMEOUT,
    ERROR_CODES.NETWORK_CONNECTION_FAILED,
    ERROR_CODES.API_SERVER_ERROR,
    ERROR_CODES.API_RATE_LIMITED
  ]

  return retryableCodes.includes(errorCode)
}

import { defineAsyncComponent, AsyncComponentLoader, Component } from 'vue'

// Loading component for better UX during async loading
const LoadingComponent = defineAsyncComponent(() => import('@/components/performance/LoadingSkeleton.vue'))

// Error component for failed loads
const ErrorComponent = defineAsyncComponent(() => import('@/components/performance/ErrorFallback.vue'))

/**
 * Enhanced lazy loading with retry mechanism and loading states
 */
export function lazyLoad(
  loader: AsyncComponentLoader,
  options: {
    delay?: number
    timeout?: number
    suspensible?: boolean
    retry?: number
    loadingComponent?: Component
    errorComponent?: Component
  } = {}
) {
  const {
    delay = 200,
    timeout = 10000,
    suspensible = false,
    retry = 3,
    loadingComponent = LoadingComponent,
    errorComponent = ErrorComponent
  } = options

  let retries = 0

  const retryLoader = async () => {
    try {
      const component = await loader()
      return component
    } catch (error) {
      if (retries < retry) {
        retries++
        console.warn(`Component loading failed, retrying (${retries}/${retry})...`)
        await new Promise(resolve => setTimeout(resolve, 1000 * retries))
        return retryLoader()
      }
      throw error
    }
  }

  return defineAsyncComponent({
    loader: retryLoader,
    loadingComponent,
    errorComponent,
    delay,
    timeout,
    suspensible
  })
}

/**
 * Lazy load routes with route-level code splitting
 */
export function lazyRoute(importFn: () => Promise<any>) {
  return lazyLoad(importFn, {
    delay: 100,
    timeout: 15000,
    retry: 2
  })
}

/**
 * Lazy load heavy components (charts, maps, etc.)
 */
export function lazyHeavyComponent(importFn: () => Promise<any>) {
  return lazyLoad(importFn, {
    delay: 300,
    timeout: 20000,
    retry: 1
  })
}

/**
 * Preload component for better performance
 */
export function preloadComponent(importFn: () => Promise<any>) {
  // Preload after a delay to not block initial render
  setTimeout(() => {
    importFn().catch(() => {
      // Silently fail - component will be loaded when needed
    })
  }, 2000)
}

/**
 * Dynamic import with retry logic
 */
export async function dynamicImport<T>(
  importFn: () => Promise<T>,
  retries = 3,
  delay = 1000
): Promise<T> {
  try {
    return await importFn()
  } catch (error) {
    if (retries > 0) {
      await new Promise(resolve => setTimeout(resolve, delay))
      return dynamicImport(importFn, retries - 1, delay * 2)
    }
    throw error
  }
}

/**
 * Performance monitoring and optimization utilities
 */

interface PerformanceMetrics {
  fcp: number | null
  lcp: number | null
  fid: number | null
  cls: number | null
  ttfb: number | null
}

class PerformanceMonitor {
  private metrics: PerformanceMetrics = {
    fcp: null,
    lcp: null,
    fid: null,
    cls: null,
    ttfb: null
  }

  private observers: PerformanceObserver[] = []

  constructor() {
    this.initializeObservers()
  }

  private initializeObservers() {
    // Largest Contentful Paint
    if ('PerformanceObserver' in window) {
      try {
        const lcpObserver = new PerformanceObserver((list) => {
          const entries = list.getEntries()
          const lastEntry = entries[entries.length - 1] as any
          this.metrics.lcp = lastEntry.startTime
        })
        lcpObserver.observe({ type: 'largest-contentful-paint', buffered: true })
        this.observers.push(lcpObserver)
      } catch (e) {
        console.warn('LCP observer not supported')
      }

      // First Input Delay
      try {
        const fidObserver = new PerformanceObserver((list) => {
          const entries = list.getEntries()
          entries.forEach((entry: any) => {
            this.metrics.fid = entry.processingStart - entry.startTime
          })
        })
        fidObserver.observe({ type: 'first-input', buffered: true })
        this.observers.push(fidObserver)
      } catch (e) {
        console.warn('FID observer not supported')
      }

      // Cumulative Layout Shift
      try {
        const clsObserver = new PerformanceObserver((list) => {
          let cls = 0
          list.getEntries().forEach((entry: any) => {
            if (!entry.hadRecentInput) {
              cls += entry.value
            }
          })
          this.metrics.cls = cls
        })
        clsObserver.observe({ type: 'layout-shift', buffered: true })
        this.observers.push(clsObserver)
      } catch (e) {
        console.warn('CLS observer not supported')
      }
    }

    // First Contentful Paint
    this.measureFCP()

    // Time to First Byte
    this.measureTTFB()
  }

  private measureFCP() {
    const paintEntries = performance.getEntriesByType('paint')
    const fcpEntry = paintEntries.find(entry => entry.name === 'first-contentful-paint')
    if (fcpEntry) {
      this.metrics.fcp = fcpEntry.startTime
    }
  }

  private measureTTFB() {
    const navigationEntries = performance.getEntriesByType('navigation') as PerformanceNavigationTiming[]
    if (navigationEntries.length > 0) {
      const entry = navigationEntries[0]
      this.metrics.ttfb = entry.responseStart - entry.requestStart
    }
  }

  getMetrics(): PerformanceMetrics {
    return { ...this.metrics }
  }

  getScore(): number {
    const { fcp, lcp, fid, cls, ttfb } = this.metrics
    let score = 100

    // FCP scoring (good: <1.8s, needs improvement: 1.8-3s, poor: >3s)
    if (fcp !== null) {
      if (fcp > 3000) score -= 20
      else if (fcp > 1800) score -= 10
    }

    // LCP scoring (good: <2.5s, needs improvement: 2.5-4s, poor: >4s)
    if (lcp !== null) {
      if (lcp > 4000) score -= 25
      else if (lcp > 2500) score -= 15
    }

    // FID scoring (good: <100ms, needs improvement: 100-300ms, poor: >300ms)
    if (fid !== null) {
      if (fid > 300) score -= 20
      else if (fid > 100) score -= 10
    }

    // CLS scoring (good: <0.1, needs improvement: 0.1-0.25, poor: >0.25)
    if (cls !== null) {
      if (cls > 0.25) score -= 20
      else if (cls > 0.1) score -= 10
    }

    // TTFB scoring (good: <200ms, needs improvement: 200-500ms, poor: >500ms)
    if (ttfb !== null) {
      if (ttfb > 500) score -= 15
      else if (ttfb > 200) score -= 5
    }

    return Math.max(0, score)
  }

  disconnect() {
    this.observers.forEach(observer => observer.disconnect())
    this.observers = []
  }
}

// Memory management utilities
export class MemoryManager {
  private cleanupFunctions: (() => void)[] = []
  private intervals: NodeJS.Timeout[] = []
  private timeouts: NodeJS.Timeout[] = []

  addCleanup(fn: () => void) {
    this.cleanupFunctions.push(fn)
  }

  addInterval(fn: () => void, delay: number): NodeJS.Timeout {
    const interval = setInterval(fn, delay)
    this.intervals.push(interval)
    return interval
  }

  addTimeout(fn: () => void, delay: number): NodeJS.Timeout {
    const timeout = setTimeout(fn, delay)
    this.timeouts.push(timeout)
    return timeout
  }

  cleanup() {
    // Clear all intervals
    this.intervals.forEach(interval => clearInterval(interval))
    this.intervals = []

    // Clear all timeouts
    this.timeouts.forEach(timeout => clearTimeout(timeout))
    this.timeouts = []

    // Run cleanup functions
    this.cleanupFunctions.forEach(fn => {
      try {
        fn()
      } catch (error) {
        console.warn('Cleanup function failed:', error)
      }
    })
    this.cleanupFunctions = []
  }

  getMemoryUsage() {
    if ('memory' in performance) {
      const memory = (performance as any).memory
      return {
        used: Math.round(memory.usedJSHeapSize / 1048576 * 100) / 100, // MB
        total: Math.round(memory.totalJSHeapSize / 1048576 * 100) / 100, // MB
        limit: Math.round(memory.jsHeapSizeLimit / 1048576 * 100) / 100 // MB
      }
    }
    return null
  }
}

// Image lazy loading with intersection observer
export function setupImageLazyLoading() {
  if ('IntersectionObserver' in window) {
    const imageObserver = new IntersectionObserver((entries, observer) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          const img = entry.target as HTMLImageElement
          const src = img.dataset.src
          if (src) {
            img.src = src
            img.removeAttribute('data-src')
            observer.unobserve(img)
          }
        }
      })
    }, {
      rootMargin: '50px 0px',
      threshold: 0.01
    })

    // Observe all images with data-src
    document.querySelectorAll('img[data-src]').forEach(img => {
      imageObserver.observe(img)
    })

    return imageObserver
  }
  return null
}

// Resource hints utilities
export function addResourceHint(href: string, rel: 'preload' | 'prefetch' | 'preconnect', as?: string) {
  const link = document.createElement('link')
  link.rel = rel
  link.href = href
  if (as) link.setAttribute('as', as)
  document.head.appendChild(link)
}

export function preloadCriticalResources() {
  // Preconnect to API
  const apiBaseUrl = import.meta.env.VITE_API_BASE_URL || '/api'
  // Only preconnect if we have a full URL (not relative path)
  if (apiBaseUrl.startsWith('http')) {
    const apiOrigin = new URL(apiBaseUrl).origin
    addResourceHint(apiOrigin, 'preconnect')
