import type { Product as ApiProduct } from '@/types'

export interface NormalizedProduct {
  id: number
  name: string
  description: string
  original_price: number
  discounted_price: number
  discount: number
  merchant: {
    name: string
    address: string
    distance: number | null
  }
  expires_at: Date | null
  available_quantity: number
  reserved_quantity: number
  category?: string
  category_id?: number | null
  image_url?: string
}

const CATEGORY_KEY_MAP: Record<string, string> = {
  'Fruits et Légumes': 'produce',
  'Boulangerie': 'bakery',
  'Plats préparés': 'prepared',
  'Épicerie': 'dairy',
  'Produits laitiers': 'dairy',
  'Viandes': 'meat'
}

type CategoryInput =
  | string
  | null
  | undefined
  | { id?: number | null; name?: string | null }

const slugify = (value: string): string => {
  return value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
}

const getCategoryBaseSlug = (name?: string | null): string | undefined => {
  if (!name) {
    return undefined
  }

  const trimmedName = name.trim()

  if (!trimmedName) {
    return undefined
  }

  return CATEGORY_KEY_MAP[trimmedName] || slugify(trimmedName)
}

export const getCategoryKey = (category?: CategoryInput): string => {
  if (!category) {
    return 'other'
  }

  let id: number | null = null
  let name: string | null | undefined

  if (typeof category === 'string') {
    name = category
  } else if (typeof category === 'object') {
    id = typeof category.id === 'number' && Number.isFinite(category.id)
      ? category.id
      : null
    name = category.name
  }

  const baseSlug = getCategoryBaseSlug(name)

  if (id !== null) {
    if (baseSlug) {
      return `${baseSlug}-${id}`
    }

    return `category-${id}`
  }

  return baseSlug || 'other'
}

export const normalizeProduct = (product: ApiProduct): NormalizedProduct => {
  const originalPrice = typeof product.original_price === 'string'
    ? parseFloat(product.original_price)
    : Number(product.original_price)

  const discountedPrice = typeof product.discounted_price === 'string'
    ? parseFloat(product.discounted_price)
    : Number(product.discounted_price)

  const discountValue = typeof product.discount_percentage === 'string'
    ? parseFloat(product.discount_percentage)
    : Number(product.discount_percentage ?? 0)

  const merchantName = (product.merchant as any)?.business_name
    || product.merchant?.name
    || 'Commerçant inconnu'

  const merchantAddress = (product.merchant as any)?.address
    || product.merchant?.city
    || 'Adresse non renseignée'

  const rawMerchantDistance = (product.merchant as any)?.distance_km
    ?? (product.merchant as any)?.distance
    ?? null

  const merchantDistance = typeof rawMerchantDistance === 'string'
    ? parseFloat(rawMerchantDistance)
    : rawMerchantDistance

  const availableQuantity = Number((product as any).available_quantity ?? product.quantity_available ?? 0)

  return {
    id: product.id,
    name: product.name,
    description: product.description || '',
    original_price: Number.isFinite(originalPrice) ? originalPrice : 0,
    discounted_price: Number.isFinite(discountedPrice) ? discountedPrice : 0,
    discount: Number.isFinite(discountValue) ? discountValue : 0,
    merchant: {
      name: merchantName,
      address: merchantAddress,
      distance: typeof merchantDistance === 'number' && !Number.isNaN(merchantDistance)
        ? merchantDistance
        : null
    },
    expires_at: product.expiration_date ? new Date(product.expiration_date) : null,
    available_quantity: Number.isFinite(availableQuantity) ? availableQuantity : 0,
    reserved_quantity: 0,
    category: getCategoryKey(product.category),
    category_id: typeof product.category?.id === 'number' && Number.isFinite(product.category.id)
      ? product.category.id
      : null,
    image_url: product.image_url || undefined
  }
}

/**
 * 🛡️ HTML Sanitization Utilities for XSS Protection
 *
 * Provides secure HTML sanitization to prevent Cross-Site Scripting (XSS) attacks
 * Uses DOMPurify for comprehensive HTML cleaning
 */

import DOMPurify from 'dompurify'

/**
 * Configuration for different sanitization levels
 */
const SANITIZATION_CONFIGS = {
  // Strictest - text only, no HTML
  TEXT_ONLY: {
    ALLOWED_TAGS: [] as string[],
    ALLOWED_ATTR: [] as string[],
    ALLOWED_CLASSES: undefined as Record<string, string[]> | undefined,
    KEEP_CONTENT: true
  },

  // Basic formatting only
  BASIC_FORMAT: {
    ALLOWED_TAGS: ['b', 'i', 'u', 'strong', 'em', 'span'],
    ALLOWED_ATTR: ['class'],
    ALLOWED_CLASSES: {
      'span': ['text-success', 'text-warning', 'text-info', 'text-error', 'inline-block', 'w-2', 'h-2', 'bg-blue-600', 'rounded-full', 'mr-2', 'mt-1.5', 'flex-shrink-0']
    } as Record<string, string[]> | undefined,
    KEEP_CONTENT: false
  },

  // For admin modal content (very restricted)
  ADMIN_MODAL: {
    ALLOWED_TAGS: ['span'],
    ALLOWED_ATTR: ['class'],
    ALLOWED_CLASSES: {
      'span': ['inline-block', 'w-2', 'h-2', 'bg-blue-600', 'rounded-full', 'mr-2', 'mt-1.5', 'flex-shrink-0', 'text-success', 'text-warning', 'text-info', 'text-error']
    } as Record<string, string[]> | undefined,
    KEEP_CONTENT: false
  }
}

/**
 * Sanitizes HTML content using DOMPurify with specified configuration
 * @param content - Raw HTML content to sanitize
 * @param level - Sanitization level to apply
 * @returns Sanitized HTML content
 */
export function sanitizeHtml(content: string, level: keyof typeof SANITIZATION_CONFIGS = 'TEXT_ONLY'): string {
  if (!content || typeof content !== 'string') {
    return ''
  }

  const config = SANITIZATION_CONFIGS[level]

  // Build config object, omitting ALLOWED_CLASSES if undefined (not a standard DOMPurify option)
  const sanitizeConfig: Record<string, unknown> = {
    ALLOWED_TAGS: config.ALLOWED_TAGS,
    ALLOWED_ATTR: config.ALLOWED_ATTR,
    KEEP_CONTENT: config.KEEP_CONTENT || false,
    // Security options
    FORBID_TAGS: ['script', 'object', 'embed', 'form', 'input', 'textarea', 'select', 'button'],
    FORBID_ATTR: ['onclick', 'onload', 'onerror', 'onmouseover', 'onfocus', 'onblur', 'onchange', 'onsubmit'],
    ALLOW_DATA_ATTR: false,
    ALLOW_UNKNOWN_PROTOCOLS: false,
    SANITIZE_DOM: true,
    WHOLE_DOCUMENT: false
  }

  return DOMPurify.sanitize(content, sanitizeConfig as Parameters<typeof DOMPurify.sanitize>[1])
}

/**
 * Sanitizes text content - strips all HTML tags
 * @param content - Content to sanitize
 * @returns Plain text content
 */
export function sanitizeText(content: string): string {
  return sanitizeHtml(content, 'TEXT_ONLY')
}

/**
 * Sanitizes content for error messages - text only
 * @param errorMessage - Error message to sanitize
 * @returns Sanitized error message
 */
export function sanitizeErrorMessage(errorMessage: string): string {
  if (!errorMessage || typeof errorMessage !== 'string') {
    return 'Une erreur inattendue s\'est produite'
  }

  // Strip all HTML and limit length
  const sanitized = sanitizeText(errorMessage)
  return sanitized.length > 500 ? sanitized.substring(0, 500) + '...' : sanitized
}

/**
 * Sanitizes URL parameters to prevent script injection
 * @param param - URL parameter value
 * @returns Sanitized parameter value
 */
export function sanitizeUrlParam(param: string | null): string {
  if (!param) return ''

  // Remove any HTML and script-like content
  return sanitizeText(param).replace(/[<>'"]/g, '')
}

/**
 * Validates and sanitizes route parameters (typically numeric IDs)
 * @param param - Route parameter
 * @returns Validated numeric ID or null
 */
export function sanitizeRouteId(param: string | undefined): number | null {
  if (!param) return null

  const sanitized = sanitizeText(param)
  const numericId = parseInt(sanitized, 10)

  return isNaN(numericId) || numericId < 1 ? null : numericId
}

/**
 * Creates safe formatted content for AdminModal
 * Replaces unsafe v-html usage with pre-sanitized content
 * @param line - Raw line content
 * @returns Sanitized formatted line
 */
export function createSafeFormattedLine(line: string): string {
  if (!line || typeof line !== 'string') {
    return ''
  }

  // First sanitize the input
  const sanitizedLine = sanitizeText(line)

  // Then apply safe formatting replacements
  const formatted = sanitizedLine
    .replace(/^• /, '<span class="inline-block w-2 h-2 bg-blue-600 rounded-full mr-2 mt-1.5 flex-shrink-0"></span>')
    .replace(/^✅ /, '<span class="text-success mr-2">✅</span>')
    .replace(/^⚠️ /, '<span class="text-warning mr-2">⚠️</span>')
    .replace(/^ℹ️ /, '<span class="text-info mr-2">ℹ️</span>')
    .replace(/^❌ /, '<span class="text-error mr-2">❌</span>')

  // Final sanitization pass with admin modal config
  return sanitizeHtml(formatted, 'ADMIN_MODAL')
}

/**
 * XSS Detection patterns for monitoring
 */
const XSS_PATTERNS = [
  /<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi,
  /javascript:/gi,
  /vbscript:/gi,
  /onload\s*=/gi,
  /onclick\s*=/gi,
  /onerror\s*=/gi,
  /onmouseover\s*=/gi,
  /<iframe\b/gi,
  /<object\b/gi,
  /<embed\b/gi,
  /expression\s*\(/gi,
  /url\s*\(/gi,
  /@import/gi
]

/**
 * Detects potential XSS attempts in content
 * @param content - Content to check
 * @returns true if potential XSS detected
 */
export function detectXssAttempt(content: string): boolean {
  if (!content || typeof content !== 'string') {
    return false
  }

  return XSS_PATTERNS.some(pattern => pattern.test(content))
}

/**
 * Logs potential XSS attempts for security monitoring
 * @param content - Suspicious content
 * @param context - Context where the content was found
 */
export function logXssAttempt(content: string, context: string): void {
  if (detectXssAttempt(content)) {
    console.warn(`🚨 Potential XSS attempt detected in ${context}:`, content.substring(0, 100))

    // In production, this should send to security monitoring service
    if (import.meta.env.PROD) {
      // Future: Integrate with security monitoring service
      // securityService.reportXssAttempt({ content, context, timestamp: new Date() })
    }
  }
}

/**
 * Safe HTML setter that replaces dangerous innerHTML usage
 * @param element - DOM element
 * @param content - HTML content to set
 * @param level - Sanitization level
 */
export function setSafeInnerHTML(element: HTMLElement, content: string, level: keyof typeof SANITIZATION_CONFIGS = 'BASIC_FORMAT'): void {
  if (!element || !content) return

  const sanitizedContent = sanitizeHtml(content, level)
  element.innerHTML = sanitizedContent
}

export default {
  sanitizeHtml,
  sanitizeText,
  sanitizeErrorMessage,
  sanitizeUrlParam,
  sanitizeRouteId,
  createSafeFormattedLine,
  detectXssAttempt,
  logXssAttempt,
  setSafeInnerHTML
}

/**
 * 🛡️ Security Headers Configuration
 *
 * Provides Content Security Policy (CSP) and other security headers
 * to prevent XSS, clickjacking, and other web security vulnerabilities
 */

/**
 * Content Security Policy configuration
 * This prevents XSS attacks by controlling which resources can be loaded
 */
export const CSP_DIRECTIVES = {
  // Default source - fallback for other directives
  'default-src': ["'self'"],

  // Script sources - only allow self and specific trusted domains
  'script-src': [
    "'self'",
    "'unsafe-inline'", // Required for Vue.js development mode
    'https://cdn.jsdelivr.net', // For external libraries
    'https://unpkg.com' // For CDN libraries
  ],

  // Style sources - allow self and inline styles for Tailwind
  'style-src': [
    "'self'",
    "'unsafe-inline'", // Required for Tailwind CSS
    'https://fonts.googleapis.com' // For Google Fonts
  ],

  // Image sources - allow self and common image CDNs
  'img-src': [
    "'self'",
    'data:', // For data URLs
    'blob:', // For blob URLs
    'https:', // HTTPS images
    'http://localhost:*' // Local development
  ],

  // Font sources
  'font-src': [
    "'self'",
    'https://fonts.gstatic.com',
    'data:' // For base64 fonts
  ],

  // Connect sources - API endpoints
  'connect-src': [
    "'self'",
    'http://localhost:*', // Local development
    'ws://localhost:*', // WebSocket for development
    'wss://localhost:*' // Secure WebSocket
  ],

  // Frame sources - prevent clickjacking
  'frame-src': ["'none'"],

  // Object sources - prevent plugin execution
  'object-src': ["'none'"],

  // Base URI - prevent injection of base tags
  'base-uri': ["'self'"],

  // Form action - restrict form submissions
  'form-action': ["'self'"]
}

/**
 * Generates CSP header value from directives
 */
export function generateCSPHeader(): string {
  return Object.entries(CSP_DIRECTIVES)
    .map(([directive, sources]) => directive + ' ' + sources.join(' '))
    .join('; ')
}

/**
 * Additional security headers for enhanced protection
 */
export const SECURITY_HEADERS = {
  // Prevent MIME type sniffing
  'X-Content-Type-Options': 'nosniff',

  // Enable XSS protection in browsers
  'X-XSS-Protection': '1; mode=block',

  // Prevent clickjacking
  'X-Frame-Options': 'DENY',

  // Control referrer information
  'Referrer-Policy': 'strict-origin-when-cross-origin',

  // Permissions policy (formerly Feature Policy)
  'Permissions-Policy': 'camera=(), microphone=(), geolocation=(self)',

  // Content Security Policy
  'Content-Security-Policy': generateCSPHeader(),

  // Strict Transport Security (HTTPS only)
  'Strict-Transport-Security': 'max-age=31536000; includeSubDomains; preload'
}

/**
 * Development-specific CSP for more relaxed policies during development
 */
export const DEV_CSP_DIRECTIVES = {
  ...CSP_DIRECTIVES,
  'script-src': [
    "'self'",
    "'unsafe-inline'",
    "'unsafe-eval'", // Required for development tools
    'http://localhost:*',
    'ws://localhost:*',
    'https://cdn.jsdelivr.net',
    'https://unpkg.com'
  ],
  'connect-src': [
    "'self'",
    'http://localhost:*',
    'ws://localhost:*',
    'wss://localhost:*',
    'http://127.0.0.1:*'
  ]
}

/**
 * Generates development-friendly CSP header
 */
export function generateDevCSPHeader(): string {
  return Object.entries(DEV_CSP_DIRECTIVES)
    .map(([directive, sources]) => directive + ' ' + sources.join(' '))
    .join('; ')
}

/**
 * Security headers for development environment
 */
export const DEV_SECURITY_HEADERS = {
  ...SECURITY_HEADERS,
  'Content-Security-Policy': generateDevCSPHeader()
}

/**
 * Applies security headers to HTML meta tags
 * This is a fallback when server-side headers aren't available
 */
export function applySecurityMetaTags(): void {
  if (typeof document === 'undefined') return

  // Add CSP meta tag
  const cspMeta = document.createElement('meta')
  cspMeta.httpEquiv = 'Content-Security-Policy'
  cspMeta.content = import.meta.env.DEV ? generateDevCSPHeader() : generateCSPHeader()
  document.head.appendChild(cspMeta)

  // Add X-Content-Type-Options
  const noSniffMeta = document.createElement('meta')
  noSniffMeta.httpEquiv = 'X-Content-Type-Options'
  noSniffMeta.content = 'nosniff'
  document.head.appendChild(noSniffMeta)

  // Add referrer policy
  const referrerMeta = document.createElement('meta')
  referrerMeta.name = 'referrer'
  referrerMeta.content = 'strict-origin-when-cross-origin'
  document.head.appendChild(referrerMeta)
}

/**
 * Validates that current page complies with CSP
 * Useful for development debugging
 */
export function validateCSPCompliance(): void {
  if (import.meta.env.PROD) return

  // Check for inline scripts
  const inlineScripts = document.querySelectorAll('script:not([src])')
  if (inlineScripts.length > 0) {
    console.warn('🚨 CSP Warning: Inline scripts detected:', inlineScripts)
  }

  // Check for inline styles
  const inlineStyles = document.querySelectorAll('style:not([data-vite-dev-id])')
  if (inlineStyles.length > 0) {
    console.warn('🚨 CSP Warning: Inline styles detected:', inlineStyles)
  }
}

export default {
  CSP_DIRECTIVES,
  SECURITY_HEADERS,
  DEV_SECURITY_HEADERS,
  generateCSPHeader,
  generateDevCSPHeader,
  applySecurityMetaTags,
  validateCSPCompliance
}

/**
 * Core Web Vitals monitoring and reporting
 */

interface WebVitalMetric {
  name: string
  value: number
  rating: 'good' | 'needs-improvement' | 'poor'
  delta: number
  id: string
}

class WebVitalsMonitor {
  private metrics: Map<string, WebVitalMetric> = new Map()
  private callbacks: ((metric: WebVitalMetric) => void)[] = []

  constructor() {
    this.initializeObservers()
  }

  onMetric(callback: (metric: WebVitalMetric) => void) {
    this.callbacks.push(callback)
  }

  private reportMetric(metric: WebVitalMetric) {
    this.metrics.set(metric.name, metric)
    this.callbacks.forEach(callback => callback(metric))

    // Log to console in development
    if (import.meta.env.DEV) {
      console.log(`🔍 ${metric.name}:`, {
        value: `${metric.value}ms`,
        rating: metric.rating,
        id: metric.id
      })
    }
  }

  private initializeObservers() {
    // Largest Contentful Paint (LCP)
    this.observeLCP()

    // First Input Delay (FID)
    this.observeFID()

    // Cumulative Layout Shift (CLS)
    this.observeCLS()

    // First Contentful Paint (FCP)
    this.observeFCP()

    // Time to First Byte (TTFB)
    this.observeTTFB()
  }

  private observeLCP() {
    if ('PerformanceObserver' in window) {
      try {
        const observer = new PerformanceObserver((list) => {
          const entries = list.getEntries()
          const lastEntry = entries[entries.length - 1] as any

          const metric: WebVitalMetric = {
            name: 'LCP',
            value: lastEntry.startTime,
            rating: this.getLCPRating(lastEntry.startTime),
            delta: lastEntry.startTime,
            id: this.generateId()
          }

          this.reportMetric(metric)
        })

        observer.observe({ type: 'largest-contentful-paint', buffered: true })
      } catch (e) {
        console.warn('LCP observer not supported')
      }
    }
  }

  private observeFID() {
    if ('PerformanceObserver' in window) {
      try {
        const observer = new PerformanceObserver((list) => {
          list.getEntries().forEach((entry: any) => {
            const value = entry.processingStart - entry.startTime

            const metric: WebVitalMetric = {
              name: 'FID',
              value,
              rating: this.getFIDRating(value),
              delta: value,
              id: this.generateId()
            }

            this.reportMetric(metric)
          })
        })

        observer.observe({ type: 'first-input', buffered: true })
      } catch (e) {
        console.warn('FID observer not supported')
      }
    }
  }

  private observeCLS() {
    if ('PerformanceObserver' in window) {
      try {
        let clsValue = 0

        const observer = new PerformanceObserver((list) => {
          list.getEntries().forEach((entry: any) => {
            if (!entry.hadRecentInput) {
              clsValue += entry.value
            }
          })

          const metric: WebVitalMetric = {
            name: 'CLS',
            value: clsValue,
            rating: this.getCLSRating(clsValue),
            delta: clsValue,
            id: this.generateId()
          }

          this.reportMetric(metric)
        })

        observer.observe({ type: 'layout-shift', buffered: true })
      } catch (e) {
        console.warn('CLS observer not supported')
      }
    }
  }

  private observeFCP() {
    const paintEntries = performance.getEntriesByType('paint')
    const fcpEntry = paintEntries.find(entry => entry.name === 'first-contentful-paint')

    if (fcpEntry) {
      const metric: WebVitalMetric = {
        name: 'FCP',
        value: fcpEntry.startTime,
        rating: this.getFCPRating(fcpEntry.startTime),
        delta: fcpEntry.startTime,
        id: this.generateId()
      }

      this.reportMetric(metric)
    }
  }

  private observeTTFB() {
    const navigationEntries = performance.getEntriesByType('navigation') as PerformanceNavigationTiming[]

    if (navigationEntries.length > 0) {
      const entry = navigationEntries[0]
      const value = entry.responseStart - entry.requestStart

      const metric: WebVitalMetric = {
        name: 'TTFB',
        value,
        rating: this.getTTFBRating(value),
        delta: value,
        id: this.generateId()
      }

      this.reportMetric(metric)
    }
  }

  private getLCPRating(value: number): 'good' | 'needs-improvement' | 'poor' {
    if (value <= 2500) return 'good'
    if (value <= 4000) return 'needs-improvement'
    return 'poor'
  }

  private getFIDRating(value: number): 'good' | 'needs-improvement' | 'poor' {
    if (value <= 100) return 'good'
    if (value <= 300) return 'needs-improvement'
    return 'poor'
  }

  private getCLSRating(value: number): 'good' | 'needs-improvement' | 'poor' {
    if (value <= 0.1) return 'good'
    if (value <= 0.25) return 'needs-improvement'
    return 'poor'
  }

  private getFCPRating(value: number): 'good' | 'needs-improvement' | 'poor' {
    if (value <= 1800) return 'good'
    if (value <= 3000) return 'needs-improvement'
    return 'poor'
  }

  private getTTFBRating(value: number): 'good' | 'needs-improvement' | 'poor' {
    if (value <= 200) return 'good'
    if (value <= 500) return 'needs-improvement'
    return 'poor'
  }

  private generateId(): string {
    const timestamp = new Date().getTime()
    const random = Math.random().toString(36).substr(2, 9)
    return `${timestamp}-${random}`
  }

  getMetrics(): WebVitalMetric[] {
    return Array.from(this.metrics.values())
  }

  getOverallScore(): number {
    const metrics = this.getMetrics()
    if (metrics.length === 0) return 0

    let score = 0
    let count = 0

    metrics.forEach(metric => {
      switch (metric.rating) {
        case 'good':
          score += 100
          break
        case 'needs-improvement':
          score += 50
          break
        case 'poor':
          score += 0
          break
      }
      count++
    })

    return Math.round(score / count)
  }
}

// Export singleton
export const webVitalsMonitor = new WebVitalsMonitor()

