/**
 * Master test runner that executes all test suites
 * This will run consumer, merchant, and admin tests sequentially
 */
import { test } from '@playwright/test'
import * as fs from 'fs'
import * as path from 'path'

test.describe.configure({ mode: 'serial' })

test.describe('Complete Application Test Suite', () => {
  test('Generate comprehensive bug report', async () => {
    console.log('\n' + '='.repeat(80))
    console.log('ANTIGASPI - COMPREHENSIVE TEST SUITE')
    console.log('='.repeat(80))

    const resultsDir = path.join(__dirname, '../../test-results')

    // Wait for all tests to complete
    await new Promise(resolve => setTimeout(resolve, 2000))

    // Collect all bug files
    const bugFiles = [
      'bugs-consumer.json',
      'bugs-merchant.json',
      'bugs-admin-ui.json'
    ]

    const allBugs: { [key: string]: string[] } = {}
    let totalBugs = 0

    for (const file of bugFiles) {
      const filePath = path.join(resultsDir, file)

      if (fs.existsSync(filePath)) {
        try {
          const content = fs.readFileSync(filePath, 'utf-8')
          const bugs = JSON.parse(content)
          const category = file.replace('bugs-', '').replace('.json', '')
          allBugs[category] = bugs
          totalBugs += bugs.length

          console.log(`\n[${category.toUpperCase()}] Found ${bugs.length} bugs`)
        } catch (e) {
          console.error(`Error reading ${file}:`, e)
        }
      }
    }

    // Generate comprehensive report
    console.log('\n' + '='.repeat(80))
    console.log(`TOTAL BUGS FOUND: ${totalBugs}`)
    console.log('='.repeat(80))

    if (totalBugs === 0) {
      console.log('\n✅ NO BUGS FOUND - ALL SYSTEMS OPERATIONAL!')
    } else {
      console.log('\n📋 BUG DETAILS BY CATEGORY:\n')

      for (const [category, bugs] of Object.entries(allBugs)) {
        if (bugs.length > 0) {
          console.log(`\n🔴 ${category.toUpperCase()} (${bugs.length} bugs):`)
          bugs.forEach((bug, index) => {
            console.log(`   ${index + 1}. ${bug}`)
          })
        }
      }
    }

    // Generate HTML report
    const htmlReport = `
<!DOCTYPE html>
<html>
<head>
  <title>Antigaspi - Test Report</title>
  <style>
    body { font-family: Arial, sans-serif; margin: 40px; background: #f5f5f5; }
    h1 { color: #333; }
    .summary { background: white; padding: 20px; border-radius: 8px; margin: 20px 0; }
    .bug-category { background: white; padding: 20px; margin: 20px 0; border-radius: 8px; }
    .bug { padding: 10px; margin: 5px 0; background: #ffe6e6; border-left: 4px solid #ff4444; }
    .success { background: #e6ffe6; border-left: 4px solid #44ff44; padding: 20px; }
    .count { font-size: 48px; font-weight: bold; color: #ff4444; }
  </style>
</head>
<body>
  <h1>🤖 Antigaspi - Comprehensive Test Report</h1>
  <div class="summary">
    <h2>Summary</h2>
    <div class="count">${totalBugs}</div>
    <p>Total bugs found across all test suites</p>
    <p>Generated: ${new Date().toLocaleString()}</p>
  </div>

  ${totalBugs === 0 ? `
    <div class="success">
      <h2>✅ All Tests Passed!</h2>
      <p>No bugs found in the application. All systems are operational.</p>
    </div>
  ` : ''}

  ${Object.entries(allBugs).map(([category, bugs]) => {
    if (bugs.length === 0) return ''
    return `
      <div class="bug-category">
        <h2>🔴 ${category.toUpperCase()} - ${bugs.length} bugs</h2>
        ${bugs.map((bug, i) => `
          <div class="bug">
            <strong>${i + 1}.</strong> ${bug}
          </div>
        `).join('')}
      </div>
    `
  }).join('')}

  <div class="summary">
    <h3>Test Coverage</h3>
    <ul>
      <li>✅ Consumer flows (signup, login, browsing, reservations)</li>
      <li>✅ Merchant flows (product management, image upload, reservations)</li>
      <li>✅ Admin flows (user management, moderation, analytics)</li>
      <li>✅ UI/UX validation (modals, notifications, forms, responsive)</li>
      <li>✅ Accessibility checks (alt texts, button labels)</li>
    </ul>
  </div>
</body>
</html>
`

    fs.writeFileSync(path.join(resultsDir, 'comprehensive-report.html'), htmlReport)
    console.log('\n📄 HTML report generated: test-results/comprehensive-report.html')

    // Generate JSON summary
    const jsonReport = {
      timestamp: new Date().toISOString(),
      totalBugs,
      bugsByCategory: allBugs,
      testCoverage: {
        consumer: allBugs['consumer']?.length || 0,
        merchant: allBugs['merchant']?.length || 0,
        adminUI: allBugs['admin-ui']?.length || 0
      }
    }

    fs.writeFileSync(
      path.join(resultsDir, 'comprehensive-report.json'),
      JSON.stringify(jsonReport, null, 2)
    )

    console.log('📄 JSON report generated: test-results/comprehensive-report.json')
    console.log('\n' + '='.repeat(80))
  })
})

import { test, expect } from '@playwright/test'
import * as fs from 'fs'

const BUGS_FOUND: string[] = []

function logBug(bug: string) {
  BUGS_FOUND.push(bug)
  console.log(`🐛 BUG FOUND: ${bug}`)
}

test.describe('Consumer Flows - Complete Journey', () => {
  test.setTimeout(120000) // 2 minutes timeout

  test('Consumer: Complete user journey from signup to reservation', async ({ page }) => {
    const timestamp = Date.now()
    const newUserEmail = `test.consumer.${timestamp}@email.com`
    const newUserPassword = 'TestPassword123!'

    // ========== 1. HOMEPAGE ==========
    console.log('\n========== TESTING HOMEPAGE ==========')
    await page.goto('http://localhost:3000')
    await page.waitForLoadState('networkidle')

    // Check hero section
    const heroTitle = page.locator('h1').first()
    if (await heroTitle.isVisible()) {
      console.log('✅ Hero title visible')
    } else {
      logBug('Hero title not visible on homepage')
    }

    // Check if products are displayed
    const productCards = page.locator('[data-testid="product-card"], .product-card, article')
    const productCount = await productCards.count()
    console.log(`Found ${productCount} products on homepage`)

    if (productCount === 0) {
      logBug('No products displayed on homepage')
    } else {
      console.log(`✅ ${productCount} products displayed`)
    }

    // Take screenshot
    await page.screenshot({ path: 'test-results/01-homepage.png', fullPage: true })

    // ========== 2. SIGNUP ==========
    console.log('\n========== TESTING SIGNUP ==========')
    const signupBtn = page.locator('a[href="/register"], button:has-text("Inscription"), a:has-text("Inscription")')

    const signupBtnExists = await signupBtn.isVisible({ timeout: 5000 }).catch(() => false)
    if (!signupBtnExists) {
      logBug('Signup button not found on homepage')
      // Try direct navigation
      await page.goto('http://localhost:3000/register')
    } else {
      await signupBtn.click()
    }
    await page.waitForURL('**/register', { timeout: 5000 }).catch(() => {})

    // Fill signup form
    await page.fill('input[name="first_name"]', 'Test')
    await page.fill('input[name="last_name"]', 'Consumer')
    await page.fill('input[type="email"]', newUserEmail)
    await page.fill('input[name="phone"]', '0123456789')
    await page.fill('input[name="city"]', 'Lomé')

    const passwordInputs = page.locator('input[type="password"]')
    const passwordCount = await passwordInputs.count()

    if (passwordCount >= 2) {
      await passwordInputs.nth(0).fill(newUserPassword)
      await passwordInputs.nth(1).fill(newUserPassword)
    } else {
      await passwordInputs.first().fill(newUserPassword)
    }

    // Check terms and conditions checkbox
    const termsCheckbox = page.locator('input[type="checkbox"]#terms, input[type="checkbox"][id="terms"]')
    if (await termsCheckbox.isVisible()) {
      await termsCheckbox.check()
    }

    // Submit form and wait for success notification
    await page.click('button[type="submit"]')

    // Wait for either success notification or error
    try {
      await page.waitForSelector('[role="status"]', { state: 'visible', timeout: 10000 })
      const notificationText = await page.locator('[role="status"]').textContent()

      if (notificationText?.toLowerCase().includes('réussie') || notificationText?.toLowerCase().includes('bienvenue')) {
        console.log('✅ Signup successful!')

        // Wait for navigation or check if already authenticated
        await page.waitForURL(/\/(dashboard|products|accueil)/, { timeout: 5000 }).catch(() => {
          // Navigation might not happen if notification blocks it, check auth state
        })
      } else {
        logBug(`Signup error: ${notificationText}`)
      }
    } catch {
      // No notification appeared, check URL
      const currentUrl = page.url()
      if (!currentUrl.includes('/register')) {
        console.log('✅ Signup succeeded (no notification but navigated)')
      } else {
        logBug(`Signup failed - still on: ${currentUrl}`)
      }
    }

    const currentUrl = page.url()
    if (currentUrl.includes('/dashboard') || currentUrl.includes('/products')) {
      console.log('✅ Signup successful - redirected to:', currentUrl)
    }

    await page.screenshot({ path: 'test-results/02-after-signup.png', fullPage: true })

    // ========== 3. LOGOUT ==========
    console.log('\n========== TESTING LOGOUT ==========')
    const logoutButton = page.locator('button:has-text("Se déconnecter"), a:has-text("Se déconnecter"), button:has-text("Déconnexion"), a:has-text("Déconnexion")')
    if (await logoutButton.isVisible()) {
      await logoutButton.click()
      await page.waitForTimeout(2000)
      console.log('✅ Logout button clicked')

      // Wait for redirect to home/login
      await page.waitForURL(/\/(login|accueil|\/)$/, { timeout: 5000 }).catch(() => {})
    } else {
      logBug('Logout button not found')
    }

    // ========== 4. LOGIN WITH NEW ACCOUNT ==========
    console.log('\n========== TESTING LOGIN ==========')
    await page.goto('http://localhost:3000/login')
    await page.waitForLoadState('networkidle')

    await page.fill('input[type="email"]', newUserEmail)
    await page.fill('input[type="password"]', newUserPassword)

    // Wait for navigation after login
    await Promise.all([
      page.waitForURL(/\/(dashboard|products)/, { timeout: 10000 }),
      page.click('button[type="submit"]')
    ]).catch(() => {
      logBug(`Login failed - still on: ${page.url()}`)
    })

    const loginUrl = page.url()
    if (loginUrl.includes('/dashboard') || loginUrl.includes('/products')) {
      console.log('✅ Login successful')
    }

    await page.screenshot({ path: 'test-results/03-after-login.png', fullPage: true })

    // ========== 5. BROWSE PRODUCTS ==========
    console.log('\n========== TESTING PRODUCT BROWSING ==========')
    await page.goto('http://localhost:3000/products')
    await page.waitForLoadState('networkidle')

    // Check search functionality
    const searchInput = page.locator('input[type="search"], input[placeholder*="Rechercher"]')
    if (await searchInput.isVisible()) {
      await searchInput.fill('pain')
      await page.waitForTimeout(1000)
      console.log('✅ Search input working')
    } else {
      logBug('Search input not found')
    }

    // Check filters
    const filterButtons = page.locator('button:has-text("Catégorie"), button:has-text("Prix"), select')
    const filterCount = await filterButtons.count()
    console.log(`Found ${filterCount} filter controls`)

    // Check product cards
    const productsAfterSearch = await page.locator('[data-testid="product-card"], .product-card, article').count()
    console.log(`Products after search: ${productsAfterSearch}`)

    await page.screenshot({ path: 'test-results/04-products-page.png', fullPage: true })

    // ========== 6. VIEW PRODUCT DETAILS ==========
    console.log('\n========== TESTING PRODUCT DETAILS ==========')
    const firstProduct = page.locator('[data-testid="product-card"], .product-card, article').first()

    if (await firstProduct.isVisible()) {
      await firstProduct.click()
      await page.waitForTimeout(2000)

      // Check product details page
      const productName = page.locator('h1, h2').first()
      const productNameText = await productName.textContent()
      console.log(`Product name: ${productNameText}`)

      // Check for price
      const priceElements = page.locator(':text("XOF"), :text("€"), :text("FCFA")')
      const priceCount = await priceElements.count()
      if (priceCount > 0) {
        console.log('✅ Price displayed')
      } else {
        logBug('Price not displayed on product details')
      }

      // Check for reserve/add to cart button
      const reserveButton = page.locator('button:has-text("Réserver"), button:has-text("Ajouter")')
      if (await reserveButton.isVisible()) {
        console.log('✅ Reserve button visible')
      } else {
        logBug('Reserve button not found on product details')
      }

      await page.screenshot({ path: 'test-results/05-product-details.png', fullPage: true })

      // ========== 7. MAKE RESERVATION ==========
      console.log('\n========== TESTING RESERVATION ==========')

      if (await reserveButton.isVisible()) {
        await reserveButton.click()

        // Wait for success notification (Toast uses role="status")
        try {
          await page.waitForSelector('[role="status"]', { state: 'visible', timeout: 5000 })
          const notificationText = await page.locator('[role="status"]').textContent()
          if (notificationText?.toLowerCase().includes('succès') || notificationText?.toLowerCase().includes('réserv')) {
            console.log('✅ Reservation success notification displayed')
          }
        } catch {
          logBug('No success notification after reservation')
        }

        await page.waitForTimeout(1000)

        // Check modal styling
        const modals = page.locator('.modal, [role="dialog"]')
        if (await modals.count() > 0) {
          const modalBg = await modals.first().evaluate((el) => {
            const styles = window.getComputedStyle(el)
            return {
              background: styles.backgroundColor,
              border: styles.border,
              padding: styles.padding
            }
          })
          console.log('Modal styles:', modalBg)

          if (modalBg.background === 'rgba(0, 0, 0, 0)' || modalBg.background === 'transparent') {
            logBug('Modal has no background - unstyled!')
          }
        }

        await page.screenshot({ path: 'test-results/06-after-reservation.png', fullPage: true })
      }
    }

    // ========== 8. VIEW DASHBOARD/RESERVATIONS ==========
    console.log('\n========== TESTING CONSUMER DASHBOARD ==========')
    await page.goto('http://localhost:3000/dashboard')
    await page.waitForLoadState('networkidle')

    // Check for reservations list
    const reservations = page.locator('[data-testid="reservation"], .reservation, table tr')
    const reservationCount = await reservations.count()
    console.log(`Found ${reservationCount} reservations in dashboard`)

    await page.screenshot({ path: 'test-results/07-consumer-dashboard.png', fullPage: true })

    // ========== 9. VIEW PROFILE ==========
    console.log('\n========== TESTING PROFILE PAGE ==========')
    await page.goto('http://localhost:3000/profile')
    await page.waitForLoadState('networkidle')

    // Check if user data is displayed
    const emailDisplay = page.locator(`:text("${newUserEmail}")`)
    if (await emailDisplay.isVisible()) {
      console.log('✅ User email displayed in profile')
    } else {
      logBug('User email not displayed in profile')
    }

    await page.screenshot({ path: 'test-results/08-profile.png', fullPage: true })

    // ========== FINAL REPORT ==========
    console.log('\n========== TEST SUMMARY ==========')
    console.log(`Total bugs found: ${BUGS_FOUND.length}`)
    if (BUGS_FOUND.length > 0) {
      console.log('\nBugs:')
      BUGS_FOUND.forEach((bug, index) => {
        console.log(`${index + 1}. ${bug}`)
      })
    } else {
      console.log('✅ No bugs found - all consumer flows working!')
    }

    // Save bugs to file
    fs.writeFileSync('test-results/bugs-consumer.json', JSON.stringify(BUGS_FOUND, null, 2))
  })
})

import { test, expect } from '@playwright/test'
import path from 'path'
import * as fs from 'fs'

const BUGS_FOUND: string[] = []

function logBug(bug: string) {
  BUGS_FOUND.push(bug)
  console.log(`🐛 BUG FOUND: ${bug}`)
}

test.describe('Merchant Flows - Complete Management', () => {
  test.setTimeout(120000) // 2 minutes timeout

  test('Merchant: Complete product and reservation management', async ({ page }) => {
    const timestamp = Date.now()

    // ========== 1. LOGIN AS MERCHANT ==========
    console.log('\n========== MERCHANT LOGIN ==========')
    await page.goto('http://localhost:3000/login')
    await page.waitForLoadState('networkidle')

    await page.fill('input[type="email"]', 'marie.martin@email.com')
    await page.fill('input[type="password"]', 'password')

    // Wait for navigation to merchant area
    await Promise.all([
      page.waitForURL(/\/merchant/, { timeout: 10000 }),
      page.click('button[type="submit"]')
    ]).catch(() => {
      logBug(`Merchant login failed - URL: ${page.url()}`)
    })

    const currentUrl = page.url()
    if (currentUrl.includes('/merchant')) {
      console.log('✅ Merchant logged in successfully')
    } else {
      logBug('Merchant login redirect failed')
    }

    await page.screenshot({ path: 'test-results/merchant-01-login.png', fullPage: true })

    // ========== 2. MERCHANT DASHBOARD ==========
    console.log('\n========== TESTING MERCHANT DASHBOARD ==========')
    await page.goto('http://localhost:3000/merchant/dashboard')
    await page.waitForLoadState('networkidle')

    // Check for statistics cards
    const statsCards = page.locator('[data-testid="stat-card"], .stat-card, .card')
    const statsCount = await statsCards.count()
    console.log(`Found ${statsCount} statistics cards`)

    if (statsCount === 0) {
      logBug('No statistics displayed on merchant dashboard')
    }

    // Check for charts/graphs
    const charts = page.locator('canvas, svg[class*="chart"]')
    const chartsCount = await charts.count()
    console.log(`Found ${chartsCount} charts`)

    await page.screenshot({ path: 'test-results/merchant-02-dashboard.png', fullPage: true })

    // ========== 3. PRODUCTS LIST ==========
    console.log('\n========== TESTING PRODUCTS LIST ==========')
